//! What the view and annotation commands share: views found by name or id, element fields read
//! with defaults, GUID references, rounding to the micron, and the default 3D view.

use crate::json::{Map, Value};
use crate::project::Project;

pub type R<T> = Result<T, String>;

pub use crate::commands::params::{get, given, has, id_of, mm_of, num_of, point3_of, point_of, points_of};

// ---------------------------------------------------------------- numbers

/// A length rounded to the micron, as the original keeps the points it works out.
pub fn r3(x: f64) -> f64 {
    let y = (x * 1000.0).round() / 1000.0;
    if y == 0.0 {
        0.0
    } else {
        y
    }
}

/// A point rounded to the micron.
pub fn r3p(p: [f64; 2]) -> [f64; 2] {
    [r3(p[0]), r3(p[1])]
}

/// A float as Rust's Display shows it in the original's messages (1.5, 17, 1000000000).
pub fn disp(x: f64) -> String {
    format!("{}", x)
}

// ---------------------------------------------------------------- element fields

pub fn cat(e: &Value) -> &str {
    e.get("category").and_then(|c| c.as_str()).unwrap_or("")
}

/// The category of an element by id ("" if there is none).
pub fn cat_of(pr: &Project, id: u64) -> String {
    pr.el(id).map(|e| cat(e).to_string()).unwrap_or_default()
}

/// "wall 100002", as the original's messages name an element.
pub fn cat_id(pr: &Project, id: u64) -> String {
    format!("{} {}", cat_of(pr, id), id)
}

pub fn s_of<'a>(e: &'a Value, k: &str) -> Option<&'a str> {
    e.get(k).and_then(|x| x.as_str())
}

pub fn f_of(e: &Value, k: &str) -> Option<f64> {
    e.get(k).and_then(|x| x.as_f64())
}

pub fn pt_of(e: &Value, k: &str) -> Option<[f64; 2]> {
    let a = e.get(k)?.as_arr()?;
    if a.len() < 2 {
        return None;
    }
    Some([a[0].as_f64()?, a[1].as_f64()?])
}

pub fn pt3_of(e: &Value, k: &str) -> Option<[f64; 3]> {
    let a = e.get(k)?.as_arr()?;
    if a.len() < 3 {
        return None;
    }
    Some([a[0].as_f64()?, a[1].as_f64()?, a[2].as_f64()?])
}

pub fn pts_of(e: &Value, k: &str) -> Option<Vec<[f64; 2]>> {
    let a = e.get(k)?.as_arr()?;
    a.iter()
        .map(|p| {
            let q = p.as_arr()?;
            if q.len() < 2 {
                return None;
            }
            Some([q[0].as_f64()?, q[1].as_f64()?])
        })
        .collect()
}

pub fn pt_value(p: [f64; 2]) -> Value {
    Value::from(p)
}

pub fn pts_value(ps: &[[f64; 2]]) -> Value {
    Value::Arr(ps.iter().map(|p| Value::from(*p)).collect())
}

/// The element's name ("" without one).
pub fn name_of(pr: &Project, id: u64) -> String {
    pr.el(id).and_then(|e| s_of(e, "name")).unwrap_or("").to_string()
}

// ---------------------------------------------------------------- references by GUID

/// The id of the element a GUID field names.
pub fn ref_id(pr: &Project, e: &Value, k: &str) -> Option<u64> {
    let g = s_of(e, k)?;
    pr.find_guid(g)
}

pub fn guid(pr: &Project, id: u64) -> String {
    pr.guid_of(id).unwrap_or_default()
}

/// The library entry name a GUID field of an element names.
pub fn lib_ref_name(pr: &Project, e: &Value, k: &str) -> Option<String> {
    let g = s_of(e, k)?;
    pr.lib_name(g)
}

// ---------------------------------------------------------------- views

/// The categories that are views of the model or of paper.
pub const VIEW_CATEGORIES: &[&str] = &["level", "planview", "section", "elevation", "view3d", "sheet", "schedule"];

pub fn is_view_category(c: &str) -> bool {
    VIEW_CATEGORIES.contains(&c)
}

/// A plan: a level's own plan (the level) or a plan view of it.
pub fn is_plan(pr: &Project, id: u64) -> bool {
    matches!(cat_of(pr, id).as_str(), "level" | "planview")
}

/// The level a plan shows (a level is its own plan).
pub fn plan_level(pr: &Project, id: u64) -> Option<u64> {
    crate::model::level_of_view(pr, id)
}

/// A view's name as messages give it: a sheet by its number.
pub fn view_name(pr: &Project, id: u64) -> String {
    match pr.el(id) {
        Some(e) if cat(e) == "sheet" => s_of(e, "number").unwrap_or("").to_string(),
        Some(e) => s_of(e, "name").unwrap_or("").to_string(),
        None => String::new(),
    }
}

/// A view given by id (any element: what it isn't is the command's to say) or by name: a level's,
/// a plan view's, a section's, an elevation's, a 3D view's or a schedule's name, or a sheet's
/// number. "`view`: X is not a view" for an id the project hasn't (or what is neither a number
/// nor text), "no view named `X`" for a name none has.
pub fn find_view(pr: &Project, cmd: &str, key: &str, v: &Value) -> R<u64> {
    let not = || format!("{}: `{}`: {} is not a view", cmd, key, v.to_compact());
    match v {
        Value::Num(_) => {
            let id = id_of(v).ok_or_else(not)?;
            if pr.elements.contains_key(&id) {
                Ok(id)
            } else {
                Err(not())
            }
        }
        Value::Str(s) => {
            if let Some(id) = find_view_named(pr, s) {
                return Ok(id);
            }
            if let Ok(id) = s.trim().parse::<u64>() {
                if pr.elements.contains_key(&id) {
                    return Ok(id);
                }
            }
            if let Some(g) = crate::model::normalize_guid(s) {
                if let Some(id) = pr.find_guid(&g) {
                    return Ok(id);
                }
            }
            Err(format!("{}: no view named `{}`", cmd, s))
        }
        _ => Err(not()),
    }
}

/// The view of this name (a sheet by its number), the first by id.
pub fn find_view_named(pr: &Project, name: &str) -> Option<u64> {
    for (id, e) in &pr.elements {
        let c = cat(e);
        if c == "sheet" {
            if s_of(e, "number") == Some(name) {
                return Some(*id);
            }
        } else if is_view_category(c) && s_of(e, "name") == Some(name) {
            return Some(*id);
        }
    }
    None
}

/// The `view` parameter (or `key`), if given (null is not given).
pub fn view_param(pr: &Project, cmd: &str, p: &Value, key: &str) -> R<Option<u64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => find_view(pr, cmd, key, v).map(Some),
    }
}

/// The lowest level, the plan commands draw in without a view.
pub fn default_plan(pr: &Project) -> Option<u64> {
    crate::model::default_level(pr)
}

/// The name the default 3D view goes by.
pub const DEFAULT_3D: &str = "{3D}";

/// Whether a view name is the default 3D view's (in any case).
pub fn is_default_3d_name(s: &str) -> bool {
    s.to_lowercase() == "{3d}"
}

/// The default 3D view, if it has come to be.
pub fn default_3d(pr: &Project) -> Option<u64> {
    pr.elements
        .iter()
        .find(|(_, e)| cat(e) == "view3d" && s_of(e, "name") == Some(DEFAULT_3D) && e.get("camera").is_none())
        .map(|(id, _)| *id)
        .or_else(|| {
            pr.elements
                .iter()
                .find(|(_, e)| cat(e) == "view3d" && s_of(e, "name") == Some(DEFAULT_3D))
                .map(|(id, _)| *id)
        })
}

/// The default 3D view, made as the original makes it when it is first changed or placed.
pub fn ensure_default_3d(pr: &mut Project) -> u64 {
    if let Some(id) = default_3d(pr) {
        return id;
    }
    let id = pr.alloc_id();
    pr.elements.insert(
        id,
        jobj! {
            "guid" => crate::rand::guid(),
            "category" => "view3d",
            "name" => DEFAULT_3D,
            "azimuth" => -45.0,
            "elevation" => 30.0,
        },
    );
    id
}

/// Every element of a category, by id.
pub fn ids_of(pr: &Project, c: &str) -> Vec<u64> {
    pr.ids_of(c)
}

/// An element's field as an object, made empty where it isn't one (`graphics`, `crop`…).
pub fn obj_field<'a>(e: &'a mut Value, k: &str) -> &'a mut Map {
    if !matches!(e.get(k), Some(Value::Obj(_))) {
        e.set(k, Value::obj());
    }
    e.get_mut(k).unwrap().as_obj_mut().unwrap()
}

// ---------------------------------------------------------------- languages

/// The project's language code (en by default).
pub fn lang(pr: &Project) -> String {
    pr.language()
}

/// A word of the project's language from a table of (en, pt, es, sv, cs, fr, nl, de, it).
pub fn word(pr: &Project, t: [&'static str; 9]) -> &'static str {
    let i = crate::project::LANGS.iter().position(|l| *l == pr.language()).unwrap_or(0);
    t[i]
}

//! A session: the project, its file, and its undo history; commands run here.

use crate::json::Value;
use crate::project::Project;

pub struct Step {
    pub before: Project,
    pub after: Project,
    pub label: String,
}

pub struct Session {
    pub project: Project,
    pub path: Option<String>,
    pub undo: Vec<Step>,
    pub redo: Vec<Step>,
    pub read_only: bool,
    /// The phase and design option this session makes elements in.
    pub now_phase: Option<String>,
    pub now_option: Option<String>,
}

pub const MAX_UNDO: usize = 200;

impl Session {
    pub fn new() -> Session {
        Session {
            project: Project::new("en"),
            path: None,
            undo: Vec::new(),
            redo: Vec::new(),
            read_only: false,
            now_phase: None,
            now_option: None,
        }
    }

    /// Runs a command by id (or alias, any case) with its parameters.
    pub fn execute(&mut self, id: &str, params: &Value) -> Result<Value, String> {
        let Some((cid, label)) = crate::commands::resolve(id) else {
            return Err(format!("unknown command `{}`; list_commands shows them", id));
        };
        let before = self.project.clone();
        // the phase and option this session makes elements in go back with a refused command
        let now_before = (self.now_phase.clone(), self.now_option.clone());
        let res = crate::commands::run(self, &cid, params);
        match res {
            Ok(out) => {
                if crate::commands::changes_model(&cid) && !crate::commands::is_history_cmd(&cid) {
                    // a scan nothing places any more goes with the command that left it so
                    crate::cloud::drop_unplaced(&mut self.project);
                    // what a constrained dimension measures to follows what the command moved
                    if let Err(e) = crate::views::keep(&mut self.project) {
                        self.project = before;
                        (self.now_phase, self.now_option) = now_before;
                        return Err(e);
                    }
                    if let Err(e) = crate::check::check(&self.project) {
                        self.project = before;
                        (self.now_phase, self.now_option) = now_before;
                        return Err(e);
                    }
                    if self.project.to_value() != before.to_value() || crate::commands::always_step(&cid) {
                        self.undo.push(Step { before, after: self.project.clone(), label: label.clone() });
                        if self.undo.len() > MAX_UNDO {
                            self.undo.remove(0);
                        }
                        self.redo.clear();
                    }
                }
                Ok(out)
            }
            Err(e) => {
                self.project = before;
                (self.now_phase, self.now_option) = now_before;
                Err(e)
            }
        }
    }

    pub fn history(&self) -> Vec<String> {
        self.undo.iter().map(|s| s.label.clone()).collect()
    }
}
//! The model's rules, checked after every command that changes it.

use crate::project::Project;

pub fn check(pr: &Project) -> Result<(), String> {
    core_check(pr)?;
    crate::cloud::check(pr)?;
    crate::media::check(pr)?;
    crate::styles::check(pr)?;
    crate::arch::check(pr)?;
    crate::structure::check(pr)?;
    crate::views::check(pr)?;
    crate::edit::check(pr)?;
    crate::readers::check(pr)?;
    Ok(())
}

fn core_check(pr: &Project) -> Result<(), String> {
    let mut level_names: Vec<String> = Vec::new();
    let mut grid_names: Vec<String> = Vec::new();
    for (id, e) in &pr.elements {
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        match cat {
            "level" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if level_names.contains(&name) {
                    return Err(format!("level {}: another level is already named `{}`", id, name));
                }
                level_names.push(name);
                if let Some(ext) = e.get("extent").and_then(|x| x.as_arr()) {
                    let a = ext.first().and_then(crate::commands::params::point_of);
                    let b = ext.get(1).and_then(crate::commands::params::point_of);
                    if let (Some(a), Some(b)) = (a, b) {
                        if !(b[0] - a[0] > 1.0 && b[1] - a[1] > 1.0) {
                            return Err(format!(
                                "level {}: its extent runs from its south-west corner to its north-east one",
                                id
                            ));
                        }
                    }
                }
            }
            "grid" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if grid_names.contains(&name) {
                    return Err(format!("grid {}: another grid is already named `{}`", id, name));
                }
                grid_names.push(name);
                let a = e.get("start").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let b = e.get("end").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let len = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
                if len <= 1.0 {
                    return Err(format!("grid {}: too short ({} mm)", id, len));
                }
            }
            _ => {}
        }
    }
    Ok(())
}
//! Reading the model: `inspect` and `elements`.

use crate::json::{Map, Value};
use crate::session::Session;

pub fn inspect(s: &Session) -> Value {
    let pr = &s.project;
    let mut m = Map::new();
    let mut counts = Map::new();
    for e in pr.elements.values() {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        let n = counts.get(&c).and_then(|v| v.as_u64()).unwrap_or(0);
        counts.insert(&c, Value::u(n + 1));
    }
    m.insert("counts", Value::Obj(counts));
    m.insert("history", s.history().into());
    m.insert("language", pr.language().into());
    m.insert("name", pr.name().into());
    let levels: Vec<Value> = crate::commands::basic::level_ids_sorted(pr)
        .iter()
        .map(|id| {
            let e = pr.el(*id).unwrap();
            jobj! {"elevation" => e.get("elevation").cloned().unwrap_or(Value::Null), "id" => *id, "name" => e.get("name").cloned().unwrap_or(Value::Null)}
        })
        .collect();
    m.insert("levels", Value::Arr(levels));
    for (k, v) in crate::styles::inspect_entries(s) {
        m.insert(&k, v);
    }
    let mut views = Vec::new();
    crate::views::inspect_entries(s, &mut views);
    for (k, v) in views {
        m.insert(&k, v);
    }
    Value::Obj(m)
}

pub fn elements(s: &Session, p: &Value) -> Result<Value, String> {
    let pr = &s.project;
    let cat = p.get("category").and_then(|c| c.as_str()).map(|c| c.to_string());
    let mut out = Vec::new();
    for (id, e) in &pr.elements {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        if let Some(want) = &cat {
            if c != want {
                continue;
            }
        }
        let mut x = e.clone();
        x.set("id", Value::u(*id));
        if c == "level" {
            x.set("computation_height", Value::f(1200.0));
        }
        if c == "pointcloud" {
            crate::cloud::element_view(pr, &mut x);
        }
        // what the views and the annotation show beyond their fields
        crate::views::element_view(pr, *id, &mut x);
        out.push(x);
    }
    let n = out.len();
    Ok(jobj! {"count" => n, "elements" => Value::Arr(out), "returned" => n})
}
