/// Every name `hide`, `show` and `categories` take, as the original lists them.
pub fn drawn_names() -> Vec<&'static str> {
    let mut v: Vec<&'static str> = MODEL.to_vec();
    v.extend_from_slice(ANNOTATION);
    v.push("component");
    v.push("roomreference");
    v.push("roomseparator");
    v
}

/// The categories a view hides unless it shows them (`shown`): rooms in a 3D view, a room's
/// reference cross everywhere.
pub fn shown_kind(c: &str) -> bool {
    matches!(c, "room" | "roomreference")
}

/// The categories of elements views don't draw (so none can be hidden in one).
pub fn undrawn(c: &str) -> bool {
    matches!(c, "sheet" | "schedule" | "viewport" | "view3d" | "dimension3d" | "planview")
}

/// A name as the original keys it: its letters and digits, lowercase.
pub fn squash(s: &str) -> String {
    s.chars().filter(|c| c.is_alphanumeric()).flat_map(|c| c.to_lowercase()).collect()
}

/// A category from a name in any case, singular or plural, among `list`.
pub fn singular_in(s: &str, list: &[&str]) -> Option<String> {
    let k = squash(s);
    if list.contains(&k.as_str()) {
        return Some(k);
    }
    let mut cands: Vec<String> = Vec::new();
    if let Some(x) = k.strip_suffix("ies") {
        cands.push(format!("{}y", x));
    }
    if k.ends_with("sses") || k.ends_with("ches") || k.ends_with("shes") {
        cands.push(k[..k.len() - 2].to_string());
    }
    cands.push(k.trim_end_matches('s').to_string());
    cands.into_iter().find(|c| !c.is_empty() && list.contains(&c.as_str()))
}

/// A category views draw, else the original's message.
pub fn drawn_category(cmd: &str, s: &str) -> R<String> {
    let names = drawn_names();
    singular_in(s, &names)
        .ok_or_else(|| format!("{}: `{}` isn't a category views draw; there are: {}", cmd, s, names.join(", ")))
}

// ---------------------------------------------------------------- the keys

/// A view's graphics' keys, in the order the file holds them.
pub const GKEYS: &[&str] = &[
    "template",
    "categories",
    "filters",
    "elements",
    "phase",
    "phase_filter",
    "options",
    "scale",
    "detail",
    "style",
    "background_grid",
    "linework",
    "layers",
];

fn rank(k: &str) -> usize {
    GKEYS.iter().position(|x| *x == k).unwrap_or(usize::MAX)
}

/// Sets (or, with None, takes away) a key of a graphics map in its place.
pub fn gput(g: &mut Map, k: &str, v: Option<Value>) {
    if let Some(v) = v {
        if let Some(slot) = g.get_mut(k) {
            *slot = v;
            return;
        }
        let r = rank(k);
        let pos = g.items.iter().position(|(kk, _)| rank(kk) > r).unwrap_or(g.items.len());
        g.items.insert(pos, (k.to_string(), v));
    } else {
        g.remove(k);
    }
}

/// A map-valued key of a graphics map (empty where it has none).
pub fn gmap(g: &Map, k: &str) -> Map {
    g.get(k).and_then(|v| v.as_obj()).cloned().unwrap_or_default()
}

/// Puts a map-valued key back, taking it away where it is empty.
pub fn gput_map(g: &mut Map, k: &str, m: Map) {
    if m.is_empty() {
        gput(g, k, None);
    } else {
        gput(g, k, Some(Value::Obj(m)));
    }
}

pub fn gstr(g: &Map, k: &str) -> Option<String> {
    g.get(k).and_then(|v| v.as_str()).map(|s| s.to_string())
}

// ---------------------------------------------------------------- where an element holds them

/// The keys that come before `graphics` in each view's element.
fn before_graphics(category: &str) -> &'static [&'static str] {
    match category {
        "level" => &["guid", "category", "name", "elevation", "extent", "view_range", "crop"],
        "planview" => &["guid", "category", "level", "name", "view_range", "crop"],
        "section" | "elevation" => &["guid", "category", "name", "start", "end", "depth", "crop"],
        "view3d" => &["guid", "category", "name", "azimuth", "elevation"],
        _ => &["guid", "category", "name"],
    }
}

/// A view's own graphics (empty where it has none).
pub fn own(pr: &Project, id: u64) -> Map {
    pr.el(id).and_then(|e| e.get("graphics")).and_then(|g| g.as_obj()).cloned().unwrap_or_default()
}

/// Puts a view's graphics back in its element, in their place (taken away when empty).
pub fn store(e: &mut Value, g: Map) {
    let category = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
    let Value::Obj(m) = e else { return };
    if g.is_empty() {
        m.remove("graphics");
        return;
    }
    if let Some(slot) = m.get_mut("graphics") {
        *slot = Value::Obj(g);
        return;
    }
    let before = before_graphics(&category);
    let pos = m.items.iter().rposition(|(k, _)| before.contains(&k.as_str())).map(|i| i + 1).unwrap_or(m.items.len());
    m.items.insert(pos, ("graphics".to_string(), Value::Obj(g)));
}

pub fn store_in(pr: &mut Project, id: u64, g: Map) {
    if let Some(e) = pr.el_mut(id) {
        store(e, g);
    }
}

// ---------------------------------------------------------------- the background grid

#[derive(Clone, PartialEq, Debug)]
pub struct GridStyle {
    pub enabled: bool,
    pub color: [u8; 3],
    pub pen: u64,
}

#[derive(Clone, PartialEq, Debug)]
pub struct Grid {
    pub visible: bool,
    pub main: GridStyle,
    pub sub: GridStyle,
    pub spacing: [f64; 2],
    pub divisions: [u64; 2],
    pub rotation: f64,
}

impl Default for Grid {
    fn default() -> Grid {
        Grid {
            visible: true,
            main: GridStyle { enabled: false, color: [230, 230, 230], pen: 0 },
            sub: GridStyle { enabled: false, color: [245, 245, 245], pen: 0 },
            spacing: [1000.0, 1000.0],
            divisions: [5, 5],
            rotation: 0.0,
        }
    }
}

const GRID_RULE: &str = "spacing X/Y must be finite and between 0.001 and 1000000000 mm; divisions X/Y 1–1000, rotation -360–360 degrees, and pens 0–16";

impl Grid {
    /// The grid a file holds (its defaults where it says nothing).
    pub fn from_value(v: Option<&Value>) -> Grid {
        let mut g = Grid::default();
        let Some(v) = v else { return g };
        if let Some(b) = v.get("visible").and_then(|x| x.as_bool()) {
            g.visible = b;
        }
        for (k, st) in [("main", &mut g.main), ("sub", &mut g.sub)] {
            if let Some(s) = v.get(k) {
                if let Some(b) = s.get("enabled").and_then(|x| x.as_bool()) {
                    st.enabled = b;
                }
                if let Some(c) = s.get("color").and_then(crate::styles::common::color_of) {
                    st.color = c;
                }
                if let Some(p) = s.get("pen").and_then(|x| x.as_f64()) {
                    st.pen = p as u64;
                }
            }
        }
        if let Some(a) = v.get("spacing").and_then(|x| x.as_arr()) {
            for i in 0..2 {
                if let Some(x) = a.get(i).and_then(|x| x.as_f64()) {
                    g.spacing[i] = x;
                }
            }
        }
        if let Some(a) = v.get("divisions").and_then(|x| x.as_arr()) {
            for i in 0..2 {
                if let Some(x) = a.get(i).and_then(|x| x.as_f64()) {
                    g.divisions[i] = x as u64;
                }
            }
        }
        if let Some(r) = v.get("rotation").and_then(|x| x.as_f64()) {
            g.rotation = r;
        }
        g
    }

    pub fn to_value(&self) -> Value {
        let st = |s: &GridStyle| jobj! {"enabled" => s.enabled, "color" => color_value(s.color), "pen" => s.pen};
        jobj! {
            "visible" => self.visible,
            "main" => st(&self.main),
            "sub" => st(&self.sub),
            "spacing" => Value::Arr(vec![Value::f(self.spacing[0]), Value::f(self.spacing[1])]),
            "divisions" => Value::Arr(vec![Value::u(self.divisions[0]), Value::u(self.divisions[1])]),
            "rotation" => Value::f(self.rotation),
        }
    }

    /// Whether its numbers are ones the model takes.
    pub fn ok(&self) -> bool {
        let sp = |x: f64| x.is_finite() && (0.001..=1e9).contains(&x);
        let dv = |x: u64| (1..=1000).contains(&x);
        sp(self.spacing[0])
            && sp(self.spacing[1])
            && dv(self.divisions[0])
            && dv(self.divisions[1])
            && self.rotation.is_finite()
            && (-360.0..=360.0).contains(&self.rotation)
            && self.main.pen <= 16
            && self.sub.pen <= 16
    }

    /// The grid's own error, as the check gives it.
    pub fn rule() -> &'static str {
        GRID_RULE
    }

    /// A patch from a command over this grid (null fields leave theirs as they are).
    pub fn patched(&self, v: &Value) -> R<Grid> {
        let m = match v {
            Value::Obj(m) => m,
            _ => return Err(format!("invalid type: {}, expected struct GridPatch", v.kind_name())),
        };
        let mut g = self.clone();
        for (k, x) in sorted_items(m) {
            if x.is_null() {
                if !["visible", "main", "sub", "spacing", "divisions", "rotation"].contains(&k.as_str()) {
                    return Err(format!(
                        "unknown field `{}`, expected one of `visible`, `main`, `sub`, `spacing`, `divisions`, `rotation`",
                        k
                    ));
                }
                continue;
            }
            match k.as_str() {
                "visible" => g.visible = de_bool(&x)?,
                "main" => g.main = patch_style(&g.main, &x)?,
                "sub" => g.sub = patch_style(&g.sub, &x)?,
                "spacing" => {
                    let a = de_pair(&x, |v| f64_of(v))?;
                    g.spacing = a;
                }
                "divisions" => {
                    let a = de_pair(&x, de_u16)?;
                    g.divisions = a;
                }
                "rotation" => g.rotation = f64_of(&x)?,
                _ => {
                    return Err(format!(
                        "unknown field `{}`, expected one of `visible`, `main`, `sub`, `spacing`, `divisions`, `rotation`",
                        k
                    ))
                }
            }
        }
        Ok(g)
    }
}

fn patch_style(cur: &GridStyle, v: &Value) -> R<GridStyle> {
    let m = match v {
        Value::Obj(m) => m,
        _ => return Err(format!("invalid type: {}, expected struct GridStyle", v.kind_name())),
    };
    let mut s = cur.clone();
    for (k, x) in sorted_items(m) {
        if x.is_null() {
            if !["enabled", "color", "pen"].contains(&k.as_str()) {
                return Err(format!("unknown field `{}`, expected one of `enabled`, `color`, `pen`", k));
            }
            continue;
        }
        match k.as_str() {
            "enabled" => s.enabled = de_bool(&x)?,
            "color" => s.color = de_rgb_array(&x)?,
            "pen" => s.pen = de_pen(&x)?,
            _ => return Err(format!("unknown field `{}`, expected one of `enabled`, `color`, `pen`", k)),
        }
    }
    Ok(s)
}

fn de_pair<T: Copy + Default>(v: &Value, f: impl Fn(&Value) -> R<T>) -> R<[T; 2]> {
    let a = match v {
        Value::Arr(a) => a,
        _ => return Err(format!("invalid type: {}, expected an array of length 2", v.kind_name())),
    };
    let mut out = [T::default(); 2];
    for i in 0..2 {
        match a.get(i) {
            Some(x) => out[i] = f(x)?,
            None => return Err(format!("invalid length {}, expected an array of length 2", i)),
        }
    }
    if a.len() > 2 {
        return Err(format!("invalid length {}, expected fewer elements in array", a.len()));
    }
    Ok(out)
}

/// A command's `background_grid` (an object, or null for the defaults) over the graphics' own:
/// the grid as the file then holds it (None where it is the default).
pub fn grid_param(cmd: &str, g: &Map, v: &Value) -> R<Option<Value>> {
    if v.is_null() {
        return Ok(None);
    }
    if !matches!(v, Value::Obj(_)) {
        return Err(format!("{}: `background_grid` is an object, or null to restore defaults", cmd));
    }
    let cur = Grid::from_value(g.get("background_grid"));
    let new = cur.patched(v).map_err(|e| format!("{}: background grid: {}", cmd, e))?;
    if !new.ok() {
        return Err(format!("{}: background grid: {}", cmd, GRID_RULE));
    }
    Ok(if new == Grid::default() { None } else { Some(new.to_value()) })
}

// ---------------------------------------------------------------- templates and what they control

/// What a template can control, in its order.
pub const GROUPS: &[&str] = &["categories", "filters", "range", "phase", "options", "scale", "detail", "style", "background_grid"];

/// A group's keys in a graphics map.
pub fn group_keys(group: &str) -> &'static [&'static str] {
    match group {
        "categories" => &["categories"],
        "filters" => &["filters"],
        "phase" => &["phase", "phase_filter"],
        "options" => &["options"],
        "scale" => &["scale"],
        "detail" => &["detail"],
        "style" => &["style"],
        "background_grid" => &["background_grid"],
        _ => &[],
    }
}

/// How a refusal names a group a template controls.
pub fn group_words(group: &str) -> &'static str {
    match group {
        "categories" => "categories",
        "filters" => "filters",
        "range" => "view range",
        "phase" => "phase and phase filter",
        "options" => "design options",
        "scale" => "scale",
        "detail" => "detail level",
        "style" => "visual style",
        "background_grid" => "background grids",
        _ => "settings",
    }
}

/// The refusal of a change a view's template controls.
pub fn followed_error(cmd: &str, group: &str, template: &str) -> String {
    format!(
        "{}: its {} follow view template `{}`; change the template, or `template: null` to stop following it",
        cmd,
        group_words(group),
        template
    )
}

/// The project's view templates (name: as the file holds it).
pub fn templates(pr: &Project) -> Map {
    pr.section("view_templates").cloned().unwrap_or_default()
}

/// The template a graphics map follows: its name and its object, where the project has it.
pub fn template_of(pr: &Project, g: &Map) -> Option<(String, Value)> {
    let r = gstr(g, "template")?;
    let name = crate::styles::common::name_of_guid(pr, "view-template", &r).unwrap_or(r);
    let t = templates(pr).get(&name).cloned()?;
    Some((name, t))
}

/// What a template controls (as its file says, in their order).
pub fn controls_of(t: &Value) -> Vec<String> {
    let given: Vec<String> = t
        .get("controls")
        .and_then(|c| c.as_arr())
        .map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect())
        .unwrap_or_default();
    GROUPS.iter().filter(|g| given.iter().any(|x| x == *g)).map(|g| g.to_string()).collect()
}

/// A template's own graphics.
pub fn template_graphics(t: &Value) -> Map {
    t.get("graphics").and_then(|g| g.as_obj()).cloned().unwrap_or_default()
}

/// The graphics in force of a view whose own are `g`: what its template controls taken from it.
pub fn effective(pr: &Project, g: &Map) -> Map {
    let mut out = g.clone();
    if let Some((_, t)) = template_of(pr, g) {
        let tg = template_graphics(&t);
        for group in controls_of(&t) {
            for k in group_keys(&group) {
                gput(&mut out, k, tg.get(k).cloned());
            }
        }
    }
    out
}

/// The views whose graphics are the source of their own: a dependent plan view's are its
/// parent's.
pub fn source_of(pr: &Project, id: u64) -> u64 {
    if let Some(e) = pr.el(id) {
        if e.get("category").and_then(|c| c.as_str()) == Some("planview") {
            if let Some(p) = e.get("parent").and_then(|p| p.as_str()).and_then(|g| pr.find_guid(g)) {
                if p != id {
                    return p;
                }
            }
        }
    }
    id
}

/// The parent of a dependent plan view.
pub fn parent_of(pr: &Project, id: u64) -> Option<u64> {
    let e = pr.el(id)?;
    if e.get("category").and_then(|c| c.as_str()) != Some("planview") {
        return None;
    }
    e.get("parent").and_then(|p| p.as_str()).and_then(|g| pr.find_guid(g))
}

/// The graphics in force of a view (by id): its source's own, with its template's.
pub fn effective_of(pr: &Project, id: u64) -> Map {
    effective(pr, &own(pr, source_of(pr, id)))
}

// ---------------------------------------------------------------- names for replies

/// The categories of a graphics map with their overrides' patterns named.
pub fn named_categories(pr: &Project, g: &Map) -> Map {
    let mut out = Map::new();
    for (k, v) in &gmap(g, "categories").items {
        out.insert(k, ovr::named_override(pr, v));
    }
    out
}

/// The categories hidden (by name, sorted).
pub fn hidden_categories(g: &Map) -> Vec<String> {
    let mut v: Vec<String> = gmap(g, "categories")
        .items
        .iter()
        .filter(|(_, o)| o.get("hidden").and_then(|h| h.as_bool()).unwrap_or(false))
        .map(|(k, _)| k.clone())
        .collect();
    v.sort();
    v
}

/// The filters applied, each by name, their patterns named.
pub fn named_filters(pr: &Project, g: &Map) -> Value {
    let a = g.get("filters").and_then(|f| f.as_arr()).cloned().unwrap_or_default();
    Value::Arr(
        a.iter()
            .map(|f| {
                let mut f = ovr::named_override(pr, f);
                if let Some(Value::Str(r)) = f.get("filter") {
                    let n = crate::styles::common::name_of_guid(pr, "view-filter", r).unwrap_or_else(|| r.clone());
                    f.set("filter", Value::s(&n));
                }
                f
            })
            .collect(),
    )
}

/// The design options shown, {set: option} by name.
pub fn named_options(pr: &Project, g: &Map) -> Map {
    let mut out = Map::new();
    for (k, v) in &gmap(g, "options").items {
        let set = crate::styles::phasing::set_name_of(pr, k);
        let raw = v.as_str().map(|s| s.to_string()).unwrap_or_else(|| v.to_compact());
        let full = crate::styles::common::name_of_guid(pr, "design-option", &raw).unwrap_or(raw.clone());
        let opt = match full.strip_prefix(&format!("{}: ", set)) {
            Some(o) => o.to_string(),
            None => {
                if full != raw {
                    full.split_once(": ").map(|(_, o)| o.to_string()).unwrap_or(full.clone())
                } else {
                    full.clone()
                }
            }
        };
        out.insert(&set, Value::s(&opt));
    }
    out
}

/// The CAD drawings' layers hidden, {drawing: [layer, …]} by the drawing's name.
pub fn named_layers(pr: &Project, g: &Map) -> Map {
    let mut out = Map::new();
    for (k, v) in &gmap(g, "layers").items {
        let n = crate::styles::common::name_of_guid(pr, "cad", k).unwrap_or_else(|| k.clone());
        out.insert(&n, v.clone());
    }
    out
}

pub fn phase_name(pr: &Project, g: &Map) -> Value {
    match gstr(g, "phase") {
        Some(p) => Value::s(&crate::styles::phasing::phase_name_of(pr, &p)),
        None => Value::Null,
    }
}

pub fn phase_filter_name(pr: &Project, g: &Map) -> Value {
    match gstr(g, "phase_filter") {
        Some(p) => Value::s(&crate::styles::phasing::filter_name_of(pr, &p)),
        None => Value::Null,
    }
}

/// A graphics map with what it names by GUID named (as `elements` and `inspect` show it).
pub fn named(pr: &Project, g: &Map) -> Value {
    let mut out = Map::new();
    for (k, v) in &g.items {
        let nv = match k.as_str() {
            "template" => {
                let r = v.as_str().unwrap_or("").to_string();
                Value::s(&crate::styles::common::name_of_guid(pr, "view-template", &r).unwrap_or(r))
            }
            "categories" => Value::Obj(named_categories(pr, g)),
            "filters" => named_filters(pr, g),
            "elements" => {
                let mut m = Map::new();
                for (ek, ev) in &gmap(g, "elements").items {
                    m.insert(ek, ovr::named_override(pr, ev));
                }
                Value::Obj(m)
            }
            "phase" => phase_name(pr, g),
            "phase_filter" => phase_filter_name(pr, g),
            "options" => Value::Obj(named_options(pr, g)),
            "layers" => Value::Obj(named_layers(pr, g)),
            _ => v.clone(),
        };
        out.insert(k, nv);
    }
    Value::Obj(out)
}

/// The scale of the units' default: 1 : 100, or 1 : 96 in feet and inches.
pub fn default_scale(pr: &Project) -> f64 {
    let units = pr.get("units").and_then(|u| u.as_str()).unwrap_or("mm");
    if matches!(units, "in" | "ft" | "ft-in") {
        96.0
    } else {
        100.0
    }
}

/// A float as the file holds a number that may have been given as an integer.
pub fn num(x: f64) -> Value {
    Value::f(x)
}

/// What the background grid in force is, as a reply shows it.
pub fn grid_reply(g: &Map) -> Value {
    Grid::from_value(g.get("background_grid")).to_value()
}

/// An integer of a JSON number, as a list of ids holds one.
pub fn as_u64(v: &Value) -> Option<u64> {
    match v {
        Value::Num(Num::U(u)) => Some(*u),
        Value::Num(Num::F(f)) if *f >= 0.0 && f.fract() == 0.0 => Some(*f as u64),
        _ => None,
    }
}

//! What `graphics` and `template` change of a graphics map, parameter by parameter, with the
//! original's messages, and the check of the result.

use super::ovr;
use super::vg::{self, gmap, gput, gput_map};
use crate::commands::params::{get, id_of};
use crate::json::{Map, Value};
use crate::project::Project;

pub type R<T> = Result<T, String>;

/// " (there are: a, b)", or nothing where there are none.
pub fn there_are(names: &[String]) -> String {
    if names.is_empty() {
        String::new()
    } else {
        format!(" (there are: {})", names.join(", "))
    }
}

// ---------------------------------------------------------------- categories

fn cat_list(cmd: &str, p: &Value, key: &str) -> R<Option<Vec<String>>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Arr(a)) => {
            let mut out = Vec::new();
            for x in a {
                match x {
                    Value::Str(s) => out.push(vg::drawn_category(cmd, s)?),
                    _ => return Err(format!("{}: `{}`: {} is not a category", cmd, key, x.to_compact())),
                }
            }
            Ok(Some(out))
        }
        Some(v) => Err(format!("{}: `{}` is a list of categories, [\"walls\", \"rooms\"…], not {}", cmd, key, v.to_compact())),
    }
}

/// An override as the file holds it, changed by `f` (None where nothing is left).
fn edit_override(pr: &Project, cur: Option<&Value>, f: impl FnOnce(&mut ovr::Ovr)) -> Option<Value> {
    let mut o = cur.and_then(|v| ovr::de_override(v).ok()).unwrap_or_default();
    f(&mut o);
    let m = ovr::override_map(pr, &o, false);
    if m.is_empty() {
        None
    } else {
        Some(Value::Obj(m))
    }
}

fn put_sorted(m: &mut Map, k: &str, v: Option<Value>) {
    match v {
        Some(v) => m.insert_sorted(k, v),
        None => {
            m.remove(k);
        }
    }
}

/// `hide`: the categories hidden. Whether it was given.
pub fn hide(pr: &Project, cmd: &str, p: &Value, g: &mut Map) -> R<bool> {
    let Some(cats) = cat_list(cmd, p, "hide")? else { return Ok(false) };
    let mut m = gmap(g, "categories");
    for c in cats {
        let v = edit_override(pr, m.get(&c), |o| {
            o.hidden = true;
            o.shown = false;
        });
        put_sorted(&mut m, &c, v);
    }
    gput_map(g, "categories", m);
    Ok(true)
}

/// `show`: the categories shown again (and those hidden unless shown, shown).
pub fn show(pr: &Project, cmd: &str, p: &Value, g: &mut Map) -> R<bool> {
    let Some(cats) = cat_list(cmd, p, "show")? else { return Ok(false) };
    let mut m = gmap(g, "categories");
    for c in cats {
        let shown = vg::shown_kind(&c);
        let v = edit_override(pr, m.get(&c), |o| {
            o.hidden = false;
            if shown {
                o.shown = true;
            }
        });
        put_sorted(&mut m, &c, v);
    }
    gput_map(g, "categories", m);
    Ok(true)
}

/// `categories`: {category: override | null}, each merged into the last.
pub fn categories(pr: &Project, cmd: &str, p: &Value, g: &mut Map) -> R<bool> {
    let m = match get(p, "categories") {
        None => return Ok(false),
        Some(Value::Obj(m)) => m.clone(),
        Some(v) => return Err(format!("{}: `categories` is {{category: override}}, not {}", cmd, v.to_compact())),
    };
    let mut cats = gmap(g, "categories");
    for (k, v) in ovr::sorted_items(&m) {
        let c = vg::drawn_category(cmd, &k)?;
        if v.is_null() {
            cats.remove(&c);
            continue;
        }
        let nv = ovr::merged(pr, cats.get(&c), &v).map_err(|e| format!("{}: category `{}`: {}", cmd, c, e))?;
        put_sorted(&mut cats, &c, nv);
    }
    gput_map(g, "categories", cats);
    Ok(true)
}

// ---------------------------------------------------------------- elements

/// An element a list or a map names (its id, or its GUID).
fn element_ref(pr: &Project, cmd: &str, key: &str, v: &Value) -> R<u64> {
    let bad = || format!("{}: `{}`: {} is not an element id or GUID", cmd, key, v.to_compact());
    let id = match v {
        Value::Num(_) => id_of(v).ok_or_else(bad)?,
        Value::Str(s) => {
            if let Ok(id) = s.trim().parse::<u64>() {
                id
            } else if let Some(gd) = crate::model::normalize_guid(s) {
                match pr.find_guid(&gd) {
                    Some(id) => id,
                    None => return Err(format!("{}: no element {}", cmd, s)),
                }
            } else {
                return Err(bad());
            }
        }
        _ => return Err(bad()),
    };
    if !pr.elements.contains_key(&id) {
        return Err(format!("{}: no element {}", cmd, id));
    }
    Ok(id)
}

fn drawable(pr: &Project, cmd: &str, id: u64) -> R<()> {
    let c = pr.category(id).unwrap_or("").to_string();
    if vg::undrawn(&c) {
        return Err(format!("{}: element {} is a {}, and views don't draw those", cmd, id, c));
    }
    Ok(())
}

fn id_list(pr: &Project, cmd: &str, p: &Value, key: &str) -> R<Option<Vec<u64>>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Arr(a)) => {
            let mut out = Vec::new();
            for x in a {
                let id = element_ref(pr, cmd, key, x)?;
                drawable(pr, cmd, id)?;
                out.push(id);
            }
            Ok(Some(out))
        }
        Some(v) => Err(format!("{}: `{}` is a list of element ids, not {}", cmd, key, v.to_compact())),
    }
}

/// `hide_elements` and `show_elements`.
pub fn hide_show_elements(pr: &Project, cmd: &str, p: &Value, g: &mut Map) -> R<bool> {
    let mut given = false;
    for (key, hidden) in [("hide_elements", true), ("show_elements", false)] {
        let Some(ids) = id_list(pr, cmd, p, key)? else { continue };
        given = true;
        let mut m = gmap(g, "elements");
        for id in ids {
            let gd = pr.guid_of(id).unwrap_or_default();
            let v = edit_override(pr, m.get(&gd), |o| o.hidden = hidden);
            put_sorted(&mut m, &gd, v);
        }
        gput_map(g, "elements", m);
    }
    Ok(given)
}

/// `elements`: {id: override | null}.
pub fn elements(pr: &Project, cmd: &str, p: &Value, g: &mut Map) -> R<bool> {
    let m = match get(p, "elements") {
        None => return Ok(false),
        Some(Value::Obj(m)) => m.clone(),
        Some(v) => return Err(format!("{}: `elements` is {{id: override}}, not {}", cmd, v.to_compact())),
    };
    let mut els = gmap(g, "elements");
    for (k, v) in ovr::sorted_items(&m) {
        let id = match k.trim().parse::<u64>() {
            Ok(id) => {
                if !pr.elements.contains_key(&id) {
                    return Err(format!("{}: no element {}", cmd, id));
                }
                id
            }
            Err(_) => match crate::model::normalize_guid(&k).and_then(|gd| pr.find_guid(&gd)) {
                Some(id) => id,
                None => {
                    if crate::model::normalize_guid(&k).is_some() {
                        return Err(format!("{}: no element {}", cmd, k));
                    }
                    return Err(format!("{}: `elements`: `{}` is not an element id or GUID", cmd, k));
                }
            },
        };
        drawable(pr, cmd, id)?;
        let gd = pr.guid_of(id).unwrap_or_default();
        if v.is_null() {
            els.remove(&gd);
            continue;
        }
        let nv = ovr::merged(pr, els.get(&gd), &v).map_err(|e| format!("{}: element {}: {}", cmd, id, e))?;
        put_sorted(&mut els, &gd, nv);
    }
    gput_map(g, "elements", els);
    Ok(true)
}

// ---------------------------------------------------------------- filters

/// The project's view filters (name: as the file holds it).
pub fn view_filters(pr: &Project) -> Map {
    pr.section("view_filters").cloned().unwrap_or_default()
}

/// The view filter a name names, by its GUID; else the original's message.
pub fn filter_ref(pr: &Project, cmd: &str, name: &str) -> R<String> {
    let vf = view_filters(pr);
    if vf.contains(name) {
        if let Some(gd) = pr.lib_guid("view-filter", name) {
            return Ok(gd);
        }
    }
    let mut names: Vec<String> = vf.keys().cloned().collect();
    names.sort();
    Err(format!("{}: there's no view filter `{}`{}", cmd, name, there_are(&names)))
}

/// `filters`: the list applied, replaced.
pub fn filters(pr: &Project, cmd: &str, p: &Value, g: &mut Map) -> R<bool> {
    let a = match get(p, "filters") {
        None => return Ok(false),
        Some(Value::Arr(a)) if a.len() <= 32 => a.clone(),
        Some(v) => {
            return Err(format!(
                "{}: `filters` is [{{filter, hidden?, projection?, cut?, …}}, …] (up to 32), not {}",
                cmd,
                v.to_compact()
            ))
        }
    };
    let mut out: Vec<Value> = Vec::new();
    let mut seen: Vec<String> = Vec::new();
    for x in &a {
        let (name, o) =
            ovr::de_applied(x).map_err(|e| format!("{}: filter {}: {}", cmd, x.clone().sorted().to_compact(), e))?;
        let gd = filter_ref(pr, cmd, &name)?;
        if seen.contains(&gd) {
            return Err(format!("{}: filter `{}` is applied twice", cmd, name));
        }
        seen.push(gd.clone());
        let mut m = Map::new();
        m.insert("filter", Value::s(&gd));
        for (k, v) in ovr::override_map(pr, &o, false).items {
            m.insert(&k, v);
        }
        out.push(Value::Obj(m));
    }
    gput(g, "filters", if out.is_empty() { None } else { Some(Value::Arr(out)) });
    Ok(true)
}

// ---------------------------------------------------------------- phase and design options

fn name_or_null(cmd: &str, key: &str, v: &Value) -> R<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::Str(s) => Ok(Some(s.clone())),
        _ => Err(format!("{}: `{}` is a name, or null, not {}", cmd, key, v.to_compact())),
    }
}

/// `phase` and `phase_filter` (by name; null takes them away). Whether either was given.
pub fn phase(pr: &Project, cmd: &str, p: &Value, g: &mut Map) -> R<bool> {
    let mut given = false;
    for (key, kind) in [("phase", "phase"), ("phase_filter", "phase-filter")] {
        let Some(v) = p.get(key) else { continue };
        given = true;
        let n = name_or_null(cmd, key, v)?;
        let r = n.map(|n| pr.lib_guid(kind, &n).unwrap_or(n));
        gput(g, key, r.map(|s| Value::s(&s)));
    }
    Ok(given)
}

/// `options`: {set: option | null}.
pub fn options(pr: &Project, cmd: &str, p: &Value, g: &mut Map) -> R<bool> {
    let m = match p.get("options") {
        None => return Ok(false),
        Some(Value::Null) => return Ok(true),
        Some(Value::Obj(m)) => m.clone(),
        Some(v) => return Err(format!("{}: `options` is {{set: option}}, not {}", cmd, v.to_compact())),
    };
    let mut opts = gmap(g, "options");
    for (k, v) in ovr::sorted_items(&m) {
        let set = pr.lib_guid("option-set", &k).unwrap_or_else(|| k.clone());
        match &v {
            Value::Null => {
                opts.remove(&set);
            }
            Value::Str(o) => {
                let r = pr.lib_guid("design-option", &format!("{}: {}", k, o)).unwrap_or_else(|| o.clone());
                opts.insert_sorted(&set, Value::s(&r));
            }
            _ => {
                return Err(format!(
                    "{}: `options`: set `{}`'s option is a name, or null, not {}",
                    cmd,
                    k,
                    v.to_compact()
                ))
            }
        }
    }
    gput_map(g, "options", opts);
    Ok(true)
}

// ---------------------------------------------------------------- CAD drawings' layers

/// The layers a CAD drawing the project holds has (its table's and its entities').
pub fn cad_layers(pr: &Project, name: &str) -> Vec<String> {
    let Some(c) = pr.section("cads").and_then(|m| m.get(name).cloned()) else { return Vec::new() };
    let Some(b64) = c.get("dxf").and_then(|d| d.as_str()) else { return Vec::new() };
    let Some(z) = crate::util::base64_decode(b64) else { return Vec::new() };
    let Ok(raw) = crate::inflate::zlib_decode(&z, 1 << 30) else { return Vec::new() };
    let text = String::from_utf8_lossy(&raw).to_string();
    let lines: Vec<&str> = text.lines().map(|l| l.trim()).collect();
    let mut out: Vec<String> = Vec::new();
    let mut in_layer_table = false;
    let mut i = 0;
    let mut current = String::new();
    while i + 1 < lines.len() {
        let code = lines[i];
        let val = lines[i + 1];
        if code == "0" {
            current = val.to_string();
            if val == "TABLE" {
                in_layer_table = false;
            }
            if val == "ENDTAB" {
                in_layer_table = false;
            }
        }
        if code == "2" && current == "TABLE" && val == "LAYER" {
            in_layer_table = true;
        } else if code == "2" && current == "LAYER" && in_layer_table {
            if !out.iter().any(|x| x == val) {
                out.push(val.to_string());
            }
        } else if code == "8" && current != "LAYER" {
            if !out.iter().any(|x| x == val) {
                out.push(val.to_string());
            }
        }
        i += 2;
    }
    out
}

/// `layers`: {drawing: [layer, …] | null}, the layers of each CAD drawing hidden.
pub fn layers(pr: &Project, cmd: &str, p: &Value, g: &mut Map) -> R<bool> {
    let m = match get(p, "layers") {
        None => return Ok(false),
        Some(Value::Obj(m)) => m.clone(),
        Some(v) => return Err(format!("{}: `layers` is {{drawing: [layer, …] | null}}, not {}", cmd, v.to_compact())),
    };
    let mut ls = gmap(g, "layers");
    for (k, v) in ovr::sorted_items(&m) {
        let known = pr.section("cads").map(|c| c.contains(&k)).unwrap_or(false);
        let gd = match pr.lib_guid("cad", &k) {
            Some(gd) if known => gd,
            _ => {
                return Err(format!(
                    "{}: `layers`: the project has no CAD drawing `{}` (see `elements` of category cadimport)",
                    cmd, k
                ))
            }
        };
        match &v {
            Value::Null => {
                ls.remove(&gd);
            }
            Value::Arr(a) => {
                let have = cad_layers(pr, &k);
                let mut names: Vec<String> = Vec::new();
                for x in a {
                    let Value::Str(n) = x else {
                        return Err(format!("{}: `layers`: `{}` lists layers by name, not {}", cmd, k, x.to_compact()));
                    };
                    if !have.iter().any(|h| h == n) {
                        return Err(format!("{}: `layers`: `{}` has no layer `{}` (see `cad_layers`)", cmd, k, n));
                    }
                    if !names.contains(n) {
                        names.push(n.clone());
                    }
                }
                names.sort();
                if names.is_empty() {
                    ls.remove(&gd);
                } else {
                    ls.insert_sorted(&gd, Value::from(names));
                }
            }
            _ => {
                return Err(format!(
                    "{}: `layers`: `{}` is a list of the layers to hide, or null, not {}",
                    cmd,
                    k,
                    v.to_compact()
                ))
            }
        }
    }
    gput_map(g, "layers", ls);
    Ok(true)
}

// ---------------------------------------------------------------- the background grid

/// `background_grid`: a patch over the grid, or null for the defaults.
pub fn grid(cmd: &str, p: &Value, g: &mut Map) -> R<bool> {
    let Some(v) = p.get("background_grid") else { return Ok(false) };
    let new = vg::grid_param(cmd, g, v)?;
    gput(g, "background_grid", new);
    Ok(true)
}

// ---------------------------------------------------------------- the check

/// What the graphics map holds is the model's: transparency a percent, fill patterns the
/// project's, its phase, phase filter and design options; else the message (after the command's
/// or the view's name).
pub fn check(pr: &Project, g: &Map) -> R<()> {
    let tr = |v: &Value| v.get("transparency").and_then(|t| t.as_u64()).unwrap_or(0);
    for (k, v) in &gmap(g, "categories").items {
        let t = tr(v);
        if t > 100 {
            return Err(format!("category `{}`: transparency is a percent, 0 to 100, not {}", k, t));
        }
    }
    for (k, v) in &gmap(g, "elements").items {
        let t = tr(v);
        if t > 100 {
            return Err(format!("element {}: transparency is a percent, 0 to 100, not {}", k, t));
        }
    }
    let fl = g.get("filters").and_then(|f| f.as_arr()).cloned().unwrap_or_default();
    for f in &fl {
        let t = tr(f);
        if t > 100 {
            let r = f.get("filter").and_then(|x| x.as_str()).unwrap_or("").to_string();
            let n = crate::styles::common::name_of_guid(pr, "view-filter", &r).unwrap_or(r);
            return Err(format!("filter `{}`: transparency is a percent, 0 to 100, not {}", n, t));
        }
    }
    let known = pr.section("fill_patterns").cloned().unwrap_or_default();
    let mut all: Vec<Value> = gmap(g, "categories").items.into_iter().map(|(_, v)| v).collect();
    all.extend(gmap(g, "elements").items.into_iter().map(|(_, v)| v));
    all.extend(fl);
    for v in &all {
        for pat in ovr::patterns_in(v) {
            let n = ovr::pattern_name(pr, &pat);
            if !known.contains(&n) {
                return Err(format!("there's no fill pattern `{}`", n));
            }
        }
    }
    crate::styles::phasing::check_view_graphics(pr, &Value::Obj(g.clone()))
}

//! A view's graphics: `graphics` (Visibility/Graphics), `scale`, `detail`, `visual_style`.
//!
//! A level, a plan view, a section, an elevation and a 3D view hold `graphics` (`vg::GKEYS`, in
//! that order): what they hide and override by category, by view filter and by element, their
//! phase, phase filter and design options, scale, detail level, visual style, background grid,
//! linework and the CAD layers they hide. A dependent plan view's are its parent's; a view that
//! follows a view template takes what the template controls from it.

#![allow(unused_imports)]

pub mod edit;
pub mod ovr;
pub mod vg;

use super::common::*;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;
use vg::{gput, gstr};

/// Runs the commands of this part.
pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "graphics" => cmd_graphics(s, p),
        "scale" => cmd_scale(s, p),
        "detail" => cmd_detail(s, p),
        "visual_style" => cmd_visual_style(s, p),
        _ => Err(format!("{}: not supported here", cid)),
    }
}

// ---------------------------------------------------------------- views

/// A view a command names: an element, or the default 3D view before it comes to be.
#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Target {
    Id(u64),
    Missing3d,
}

/// The categories a view is found by name in (sheets aren't, by name or number).
fn named_view(c: &str) -> bool {
    matches!(c, "level" | "planview" | "section" | "elevation" | "view3d" | "schedule")
}

/// A view by id, by name or by GUID; `{3D}` in any case is the default 3D view, which may not be
/// yet. "`view`: X is not a view" for an id the project hasn't, "no view named `X`" for a name.
pub fn lookup_view(pr: &Project, cmd: &str, v: &Value) -> R<Target> {
    let not = || format!("{}: `view`: {} is not a view", cmd, v.to_compact());
    match v {
        Value::Num(_) => {
            let id = id_of(v).ok_or_else(not)?;
            if pr.elements.contains_key(&id) {
                Ok(Target::Id(id))
            } else {
                Err(not())
            }
        }
        Value::Str(s) => {
            for (id, e) in &pr.elements {
                if named_view(cat(e)) && s_of(e, "name") == Some(s.as_str()) {
                    return Ok(Target::Id(*id));
                }
            }
            if is_default_3d_name(s) {
                return Ok(match default_3d(pr) {
                    Some(id) => Target::Id(id),
                    None => Target::Missing3d,
                });
            }
            if let Ok(id) = s.trim().parse::<u64>() {
                return if pr.elements.contains_key(&id) { Ok(Target::Id(id)) } else { Err(not()) };
            }
            if let Some(g) = crate::model::normalize_guid(s) {
                if let Some(id) = pr.find_guid(&g) {
                    return Ok(Target::Id(id));
                }
            }
            Err(format!("{}: no view named `{}`", cmd, s))
        }
        _ => Err(not()),
    }
}

/// How a message names a view (or another element): a view by its name, a sheet by its number.
pub fn label(pr: &Project, id: u64) -> String {
    match pr.el(id) {
        Some(e) if cat(e) == "sheet" => format!("sheet {}", s_of(e, "number").unwrap_or("")),
        Some(e) if named_view(cat(e)) => s_of(e, "name").unwrap_or("").to_string(),
        Some(e) => format!("{} {}", cat(e), id),
        None => id.to_string(),
    }
}

/// The view of `view` (the lowest level's plan unless given).
fn view_or_plan(pr: &Project, cmd: &str, p: &Value) -> R<Target> {
    match get(p, "view") {
        Some(v) => lookup_view(pr, cmd, v),
        None => default_plan(pr).map(Target::Id).ok_or_else(|| format!("{}: the project has no level", cmd)),
    }
}

/// Whether a view is a plan, a section or an elevation (they have a scale and a detail level).
fn is_drawing(c: &str) -> bool {
    matches!(c, "level" | "planview" | "section" | "elevation")
}

/// Whether a view takes graphics.
pub fn takes_graphics(c: &str) -> bool {
    is_drawing(c) || c == "view3d"
}

// ---------------------------------------------------------------- graphics

/// What `graphics` replies for a view: its graphics in force (`vid` none for the default 3D view
/// before it comes to be).
pub fn view_reply(pr: &Project, vid: Option<u64>, name: &str) -> Value {
    let own = vid.map(|id| vg::own(pr, vg::source_of(pr, id))).unwrap_or_default();
    let eff = vg::effective(pr, &own);
    let tpl = vg::template_of(pr, &own);
    let controlled: Vec<String> = tpl.as_ref().map(|(_, t)| vg::controls_of(t)).unwrap_or_default();
    let mut elements = Map::new();
    let mut hidden_elements = Vec::new();
    for (gd, o) in &vg::gmap(&own, "elements").items {
        let Some(id) = pr.find_guid(gd) else { continue };
        elements.insert(&id.to_string(), ovr::named_override(pr, o));
        if o.get("hidden").and_then(|h| h.as_bool()).unwrap_or(false) {
            hidden_elements.push(Value::u(id));
        }
    }
    jobj! {
        "background_grid" => vg::grid_reply(&eff),
        "categories" => Value::Obj(vg::named_categories(pr, &eff)),
        "controlled" => controlled,
        "detail" => gstr(&eff, "detail").unwrap_or_else(|| "fine".into()),
        "elements" => Value::Obj(elements),
        "filters" => vg::named_filters(pr, &eff),
        "hidden" => vg::hidden_categories(&eff),
        "hidden_elements" => Value::Arr(hidden_elements),
        "layers" => Value::Obj(vg::named_layers(pr, &own)),
        "name" => name,
        "options" => Value::Obj(vg::named_options(pr, &eff)),
        "phase" => vg::phase_name(pr, &eff),
        "phase_filter" => vg::phase_filter_name(pr, &eff),
        "scale" => eff.get("scale").cloned().unwrap_or(Value::Null),
        "template" => tpl.map(|(n, _)| Value::s(&n)).unwrap_or(Value::Null),
        "view" => vid.map(Value::u).unwrap_or(Value::Null),
        "visual_style" => gstr(&eff, "style").unwrap_or_else(|| "shaded".into()),
    }
}

/// The refusal of a change to a dependent view.
fn dependent_error(pr: &Project, cmd: &str, id: u64, parent: u64, what: &str) -> String {
    format!(
        "{}: {} is a dependent view: it follows its parent, `{}`, in its {}; change them there",
        cmd,
        name_of(pr, id),
        name_of(pr, parent),
        what
    )
}

fn cmd_graphics(s: &mut Session, p: &Value) -> R<Value> {
    let cmd = "graphics";
    let pr = &mut s.project;
    let target = view_or_plan(pr, cmd, p)?;
    let vid = match target {
        Target::Id(id) => {
            if !takes_graphics(&cat_of(pr, id)) {
                return Err(format!("{}: {} isn't a plan, a section, an elevation or a 3D view", cmd, label(pr, id)));
            }
            Some(id)
        }
        Target::Missing3d => None,
    };
    let name = match vid {
        Some(id) => name_of(pr, id),
        None => DEFAULT_3D.to_string(),
    };
    let reset = crate::commands::params::opt_bool(p, cmd, "reset")?.unwrap_or(false);
    let src = vid.map(|id| vg::source_of(pr, id));
    let old = src.map(|id| vg::own(pr, id)).unwrap_or_default();
    let mut g = if reset { Map::new() } else { old.clone() };
    let mut cats = edit::hide(pr, cmd, p, &mut g)?;
    cats |= edit::show(pr, cmd, p, &mut g)?;
    edit::hide_show_elements(pr, cmd, p, &mut g)?;
    cats |= edit::categories(pr, cmd, p, &mut g)?;
    edit::elements(pr, cmd, p, &mut g)?;
    let filters = edit::filters(pr, cmd, p, &mut g)?;
    let phase = edit::phase(pr, cmd, p, &mut g)?;
    let options = edit::options(pr, cmd, p, &mut g)?;
    edit::layers(pr, cmd, p, &mut g)?;
    let grid = edit::grid(cmd, p, &mut g)?;
    template_param(pr, cmd, p, &mut g)?;
    if let Some((tname, t)) = vg::template_of(pr, &g) {
        let c = vg::controls_of(&t);
        for (group, given) in
            [("categories", cats), ("filters", filters), ("phase", phase), ("options", options), ("background_grid", grid)]
        {
            if given && c.iter().any(|x| x == group) {
                return Err(vg::followed_error(cmd, group, &tname));
            }
        }
    }
    if g != old {
        if let Some(id) = vid {
            if let Some(parent) = vg::parent_of(pr, id) {
                return Err(dependent_error(pr, cmd, id, parent, "graphics"));
            }
        }
    }
    edit::check(pr, &g).map_err(|e| format!("{}: {}", cmd, e))?;
    let mut vid = vid;
    if g != old {
        let id = match src {
            Some(id) => id,
            None => {
                let id = ensure_default_3d(pr);
                vid = Some(id);
                id
            }
        };
        vg::store_in(pr, id, g);
    }
    Ok(view_reply(pr, vid, &name))
}

/// `template`: the view template a view follows (by name), or null.
fn template_param(pr: &Project, cmd: &str, p: &Value, g: &mut Map) -> R<()> {
    match p.get("template") {
        None => Ok(()),
        Some(Value::Null) => {
            gput(g, "template", None);
            Ok(())
        }
        Some(Value::Str(n)) => {
            let ts = vg::templates(pr);
            if ts.contains(n) {
                let gd = pr.lib_guid("view-template", n).unwrap_or_else(|| n.clone());
                gput(g, "template", Some(Value::s(&gd)));
                Ok(())
            } else {
                let mut names: Vec<String> = ts.keys().cloned().collect();
                names.sort();
                Err(format!("{}: there's no view template `{}`{}", cmd, n, edit::there_are(&names)))
            }
        }
        Some(v) => Err(format!("{}: `template` is a view template's name, or null, not {}", cmd, v.to_compact())),
    }
}

// ---------------------------------------------------------------- scale, detail and visual style

/// The template a view (by its graphics' source) follows, where it controls `group`.
fn controlling(pr: &Project, src: u64, group: &str) -> Option<String> {
    let (n, t) = vg::template_of(pr, &vg::own(pr, src))?;
    if vg::controls_of(&t).iter().any(|x| x == group) {
        Some(n)
    } else {
        None
    }
}

/// A plan, a section or an elevation a command names.
fn drawing_view(pr: &Project, cmd: &str, p: &Value) -> R<u64> {
    let id = match view_or_plan(pr, cmd, p)? {
        Target::Id(id) => id,
        Target::Missing3d => {
            let n = get(p, "view").and_then(|v| v.as_str()).unwrap_or(DEFAULT_3D).to_string();
            return Err(format!("{}: no view named `{}`", cmd, n));
        }
    };
    if !is_drawing(&cat_of(pr, id)) {
        return Err(format!("{}: {} isn't a plan, a section or an elevation; only those have one", cmd, label(pr, id)));
    }
    Ok(id)
}

/// The n of 1 : n a scale is, from 1 to 100000.
pub fn scale_of(cmd: &str, v: &Value) -> R<f64> {
    let bad = || format!("{}: `scale` is the n of 1 : n, from 1 to 100000, not {}", cmd, v.to_compact());
    match v {
        Value::Null => Err(format!(
            "{}: `scale` is the n of 1 : n, from 1 to 100000, not null: a view always has a scale (1 : 100, or 1/8\" = 1'-0\" in feet and inches, until it is given one)",
            cmd
        )),
        Value::Num(n) => {
            let x = n.as_f64();
            if x.is_finite() && (1.0..=100000.0).contains(&x) {
                Ok(x)
            } else {
                Err(bad())
            }
        }
        _ => Err(bad()),
    }
}

/// A detail level: coarse, medium or fine (any case).
pub fn detail_of(cmd: &str, v: &Value) -> R<String> {
    if let Value::Str(s) = v {
        let k = vg::squash(s);
        if ["coarse", "medium", "fine"].contains(&k.as_str()) {
            return Ok(k);
        }
    }
    Err(format!("{}: `detail` is coarse, medium or fine, not {}", cmd, v.to_compact()))
}

/// A visual style: shaded, hidden_line or wireframe (any case, with or without the underscore).
pub fn style_of(cmd: &str, key: &str, v: &Value) -> R<String> {
    if let Value::Str(s) = v {
        match vg::squash(s).as_str() {
            "shaded" => return Ok("shaded".into()),
            "hiddenline" => return Ok("hidden_line".into()),
            "wireframe" => return Ok("wireframe".into()),
            _ => {}
        }
    }
    Err(format!("{}: `{}` is shaded, hidden_line or wireframe, not {}", cmd, key, v.to_compact()))
}

fn cmd_scale(s: &mut Session, p: &Value) -> R<Value> {
    let cmd = "scale";
    let pr = &mut s.project;
    let id = drawing_view(pr, cmd, p)?;
    let src = vg::source_of(pr, id);
    if let Some(v) = p.get("scale") {
        let x = scale_of(cmd, v)?;
        if let Some(parent) = vg::parent_of(pr, id) {
            return Err(dependent_error(pr, cmd, id, parent, "scale"));
        }
        if let Some(t) = controlling(pr, src, "scale") {
            return Err(vg::followed_error(cmd, "scale", &t));
        }
        let mut g = vg::own(pr, src);
        gput(&mut g, "scale", Some(Value::f(x)));
        vg::store_in(pr, src, g);
    }
    let eff = vg::effective_of(pr, id);
    let sc = eff.get("scale").and_then(|x| x.as_f64()).unwrap_or_else(|| vg::default_scale(pr));
    Ok(jobj! {"name" => name_of(pr, id), "scale" => Value::f(sc), "view" => id})
}

fn cmd_detail(s: &mut Session, p: &Value) -> R<Value> {
    let cmd = "detail";
    let pr = &mut s.project;
    let id = drawing_view(pr, cmd, p)?;
    let src = vg::source_of(pr, id);
    if let Some(v) = get(p, "detail") {
        let d = detail_of(cmd, v)?;
        if let Some(parent) = vg::parent_of(pr, id) {
            return Err(dependent_error(pr, cmd, id, parent, "detail level"));
        }
        if let Some(t) = controlling(pr, src, "detail") {
            return Err(vg::followed_error(cmd, "detail", &t));
        }
        let mut g = vg::own(pr, src);
        gput(&mut g, "detail", if d == "fine" { None } else { Some(Value::s(&d)) });
        vg::store_in(pr, src, g);
    }
    let eff = vg::effective_of(pr, id);
    let d = gstr(&eff, "detail").unwrap_or_else(|| "fine".into());
    Ok(jobj! {"detail" => d, "name" => name_of(pr, id), "view" => id})
}

fn cmd_visual_style(s: &mut Session, p: &Value) -> R<Value> {
    let cmd = "visual_style";
    let pr = &mut s.project;
    let target = match get(p, "view") {
        Some(v) => lookup_view(pr, cmd, v)?,
        None => match default_3d(pr) {
            Some(id) => Target::Id(id),
            None => Target::Missing3d,
        },
    };
    let mut vid = match target {
        Target::Id(id) => {
            if cat_of(pr, id) != "view3d" {
                return Err(format!("{}: {} isn't a 3D view; only those have a visual style", cmd, label(pr, id)));
            }
            Some(id)
        }
        Target::Missing3d => None,
    };
    if let Some(v) = get(p, "style") {
        let st = style_of(cmd, "style", v)?;
        if let Some(id) = vid {
            if let Some(t) = controlling(pr, id, "style") {
                return Err(vg::followed_error(cmd, "style", &t));
            }
        }
        let old = vid.map(|id| vg::own(pr, id)).unwrap_or_default();
        let mut g = old.clone();
        gput(&mut g, "style", if st == "shaded" { None } else { Some(Value::s(&st)) });
        if g != old {
            let id = match vid {
                Some(id) => id,
                None => ensure_default_3d(pr),
            };
            vid = Some(id);
            vg::store_in(pr, id, g);
        }
    }
    let eff = vid.map(|id| vg::effective_of(pr, id)).unwrap_or_default();
    let st = gstr(&eff, "style").unwrap_or_else(|| "shaded".into());
    Ok(jobj! {"style" => st, "view" => vid.map(Value::u).unwrap_or(Value::Null)})
}

// ---------------------------------------------------------------- the model's rules

/// The model rules of this part, checked after every command: what each view's graphics hold is
/// the model's.
pub fn check(pr: &Project) -> R<()> {
    for (id, e) in &pr.elements {
        let Some(Value::Obj(g)) = e.get("graphics") else { continue };
        if !takes_graphics(cat(e)) {
            continue;
        }
        let pre = |m: String| format!("{} {}: {}", cat(e), id, m);
        edit::check(pr, g).map_err(pre)?;
        if let Some(bg) = g.get("background_grid") {
            if !vg::Grid::from_value(Some(bg)).ok() {
                return Err(pre(format!("background grid: {}", vg::Grid::rule())));
            }
        }
        if let Some(sc) = g.get("scale").and_then(|x| x.as_f64()) {
            if !(1.0..=100000.0).contains(&sc) {
                return Err(pre(format!("`scale` is the n of 1 : n, from 1 to 100000, not {}", sc)));
            }
        }
    }
    Ok(())
}

/// What `elements` shows of a view's graphics: what they name by GUID, named.
pub fn element_view(pr: &Project, _id: u64, x: &mut Value) {
    if let Some(Value::Obj(g)) = x.get("graphics").cloned() {
        x.set("graphics", vg::named(pr, &g));
    }
}

