/// What the graphics map holds is the model's: transparency a percent, fill patterns the
/// project's, its phase, phase filter and design options; else the message (after the command's
/// or the view's name).
pub fn check(pr: &Project, g: &Map) -> R<()> {
    let tr = |v: &Value| v.get("transparency").and_then(|t| t.as_u64()).unwrap_or(0);
    for (k, v) in &gmap(g, "categories").items {
        let t = tr(v);
        if t > 100 {
            return Err(format!("category `{}`: transparency is a percent, 0 to 100, not {}", k, t));
        }
    }
    for (k, v) in &gmap(g, "elements").items {
        let t = tr(v);
        if t > 100 {
            return Err(format!("element {}: transparency is a percent, 0 to 100, not {}", k, t));
        }
    }
    let fl = g.get("filters").and_then(|f| f.as_arr()).cloned().unwrap_or_default();
    for f in &fl {
        let t = tr(f);
        if t > 100 {
            let r = f.get("filter").and_then(|x| x.as_str()).unwrap_or("").to_string();
            let n = crate::styles::common::name_of_guid(pr, "view-filter", &r).unwrap_or(r);
            return Err(format!("filter `{}`: transparency is a percent, 0 to 100, not {}", n, t));
        }
    }
    let known = pr.section("fill_patterns").cloned().unwrap_or_default();
    let mut all: Vec<Value> = gmap(g, "categories").items.into_iter().map(|(_, v)| v).collect();
    all.extend(gmap(g, "elements").items.into_iter().map(|(_, v)| v));
    all.extend(fl);
    for v in &all {
        for pat in ovr::patterns_in(v) {
            let n = ovr::pattern_name(pr, &pat);
            if !known.contains(&n) {
                return Err(format!("there's no fill pattern `{}`", n));
            }
        }
    }
    crate::styles::phasing::check_view_graphics(pr, &Value::Obj(g.clone()))
}

