//! A stand-in for the schedules' fields that view filters' rules read: each category's fields
//! (as `schedule {category}`'s `available` lists them, project parameters after), what kind of
//! value each holds, each element's value, and how a rule compares them (text in any case,
//! numbers as the schedule shows them, an unset yes or no as no).

use crate::json::Value;
use crate::project::Project;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Kind {
    Text,
    Length,
    Area,
    Number,
    YesNo,
}

impl Kind {
    /// How a rule's error names what the field compares.
    pub fn compares(self) -> &'static str {
        match self {
            Kind::Text => "text",
            Kind::Length => "a length (mm)",
            Kind::Area => "an area (m²)",
            Kind::Number => "a number",
            Kind::YesNo => "yes or no",
        }
    }

    pub fn holds(self) -> &'static str {
        match self {
            Kind::Text => "text",
            Kind::Length => "a length",
            Kind::Area => "an area",
            Kind::Number => "a number",
            Kind::YesNo => "yes or no",
        }
    }
}

/// A field's value of an element.
#[derive(Clone, PartialEq, Debug)]
pub enum FV {
    Text(String),
    Num(f64),
    Bool(bool),
}

use Kind::*;

const PHASING: &[(&str, Kind)] = &[("Phase Created", Text), ("Phase Demolished", Text), ("Design Option", Text)];

/// A category's own fields, in the schedule's order.
fn own_fields(cat: &str) -> Vec<(&'static str, Kind)> {
    let base: &[(&str, Kind)] = match cat {
        "room" => &[
            ("Number", Text),
            ("Name", Text),
            ("Level", Text),
            ("Area", Area),
            ("Perimeter", Length),
            ("Count", Number),
            ("Unbounded Height", Length),
            ("Volume", Number),
        ],
        "door" => &[
            ("Mark", Text),
            ("Type", Text),
            ("Width", Length),
            ("Height", Length),
            ("Level", Text),
            ("Wall", Number),
            ("Family", Text),
            ("Operation", Text),
            ("Count", Number),
        ],
        "window" => &[
            ("Mark", Text),
            ("Type", Text),
            ("Width", Length),
            ("Height", Length),
            ("Sill", Length),
            ("Level", Text),
            ("Wall", Number),
            ("Family", Text),
            ("Operation", Text),
            ("Count", Number),
        ],
        "wall" => &[
            ("Id", Number),
            ("Type", Text),
            ("Level", Text),
            ("Length", Length),
            ("Height", Length),
            ("Thickness", Length),
            ("Count", Number),
        ],
        "floor" => &[
            ("Id", Number),
            ("Type", Text),
            ("Level", Text),
            ("Area", Area),
            ("Thickness", Length),
            ("Offset", Length),
            ("Count", Number),
            ("Structural", YesNo),
        ],
        "ceiling" => &[
            ("Id", Number),
            ("Type", Text),
            ("Level", Text),
            ("Offset", Length),
            ("Area", Area),
            ("Thickness", Length),
            ("Count", Number),
        ],
        "roof" => &[
            ("Id", Number),
            ("Type", Text),
            ("Level", Text),
            ("Slope", Number),
            ("Plan Area", Area),
            ("Offset", Length),
            ("Count", Number),
        ],
        "column" | "structuralcolumn" => &[
            ("Id", Number),
            ("Type", Text),
            ("Level", Text),
            ("Width", Length),
            ("Depth", Length),
            ("Height", Length),
            ("Count", Number),
        ],
        "footing" => &[
            ("Id", Number),
            ("Type", Text),
            ("Level", Text),
            ("Width", Length),
            ("Depth", Length),
            ("Thickness", Length),
            ("Count", Number),
        ],
        "beam" | "stripfooting" => &[
            ("Id", Number),
            ("Type", Text),
            ("Level", Text),
            ("Length", Length),
            ("Width", Length),
            ("Depth", Length),
            ("System", Text),
            ("Count", Number),
        ],
        "rebar" => &[
            ("Id", Number),
            ("Level", Text),
            ("Grade", Text),
            ("Diameter", Length),
            ("Length", Length),
            ("Count", Number),
            ("Weight", Number),
            ("Host", Number),
            ("Layer", Text),
        ],
        "pipe" | "conduit" | "cable" | "wire" => &[
            ("Id", Number),
            ("Type", Text),
            ("Level", Text),
            ("System", Text),
            ("Length", Length),
            ("Diameter", Length),
            ("Count", Number),
        ],
        "cabletray" | "duct" | "downconductor" | "groundconductor" => &[
            ("Id", Number),
            ("Type", Text),
            ("Level", Text),
            ("System", Text),
            ("Length", Length),
            ("Width", Length),
            ("Depth", Length),
            ("Count", Number),
        ],
        "component" => &[("Family", Text), ("Type", Text), ("Level", Text), ("Count", Number)],
        "stair" => &[
            ("Id", Number),
            ("Level", Text),
            ("Width", Length),
            ("Height", Length),
            ("Risers", Number),
            ("Riser Height", Length),
            ("Tread", Length),
            ("Length", Length),
            ("Count", Number),
        ],
        "ramp" => &[
            ("Id", Number),
            ("Level", Text),
            ("Width", Length),
            ("Height", Length),
            ("Length", Length),
            ("Slope", Number),
            ("Count", Number),
        ],
        "railing" => &[("Id", Number), ("Type", Text), ("Level", Text), ("Length", Length), ("Height", Length), ("Count", Number)],
        "mass" => &[
            ("Name", Text),
            ("Level", Text),
            ("Height", Length),
            ("Area", Area),
            ("Volume", Number),
            ("Gross Floor Area", Area),
            ("Count", Number),
        ],
        "massfloor" => &[
            ("Mass", Text),
            ("Level", Text),
            ("Area", Area),
            ("Perimeter", Length),
            ("Volume", Number),
            ("Count", Number),
        ],
        "level" => &[("Elevation", Length), ("Name", Text), ("Count", Number)],
        _ => &[],
    };
    let mut v = base.to_vec();
    if !matches!(cat, "rebar" | "massfloor" | "level") {
        v.extend_from_slice(PHASING);
    }
    v
}

/// The kind of a family parameter as a schedule compares it.
fn param_kind(k: &str) -> Kind {
    match k {
        "length" => Length,
        "yesno" => YesNo,
        "material" | "text" => Text,
        _ => Number,
    }
}

/// The project parameters of a category: (name, kind, GUID).
fn project_params(pr: &Project, cat: &str) -> Vec<(String, Kind, Option<String>)> {
    let mut out = Vec::new();
    if let Some(m) = pr.section("parameters") {
        for (name, v) in &m.items {
            let cats: Vec<String> = v
                .get("categories")
                .and_then(|c| c.as_arr())
                .map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect())
                .unwrap_or_default();
            if !cats.iter().any(|c| c == cat) {
                continue;
            }
            let kind = param_kind(v.get("kind").and_then(|k| k.as_str()).unwrap_or("text"));
            out.push((name.clone(), kind, pr.lib_guid("parameter", name)));
        }
    }
    out
}

/// A field a rule names, of a category: its name, kind and, for a project parameter, its GUID.
#[derive(Clone, Debug)]
pub struct Field {
    pub name: String,
    pub kind: Kind,
    pub param: Option<String>,
}

/// Every field of a category, in the order its schedule lists them.
pub fn fields_of(pr: &Project, cat: &str) -> Vec<Field> {
    let mut out: Vec<Field> =
        own_fields(cat).into_iter().map(|(n, k)| Field { name: n.to_string(), kind: k, param: None }).collect();
    if cat == "component" {
        // the families' parameters, family by family in name order, each once
        if let Some(fams) = pr.section("families") {
            let mut names: Vec<&String> = fams.keys().collect();
            names.sort();
            for f in names {
                let params = fams.get(f).and_then(|x| x.get("parameters")).and_then(|x| x.as_arr()).cloned().unwrap_or_default();
                for p in params {
                    let Some(n) = p.get("name").and_then(|x| x.as_str()) else { continue };
                    if out.iter().any(|x| x.name == n) {
                        continue;
                    }
                    let k = param_kind(p.get("kind").and_then(|x| x.as_str()).unwrap_or("length"));
                    out.push(Field { name: n.to_string(), kind: k, param: None });
                }
            }
        }
    }
    for (n, k, g) in project_params(pr, cat) {
        if out.iter().any(|x| x.name == n) {
            continue;
        }
        out.push(Field { name: n, kind: k, param: g });
    }
    out
}

/// A field of a category by name or, for a project parameter, its GUID.
pub fn field(pr: &Project, cat: &str, name: &str) -> Option<Field> {
    fields_of(pr, cat).into_iter().find(|f| f.name == name || f.param.as_deref() == Some(name))
}

// ---------------------------------------------------------------- values

fn s<'a>(e: &'a Value, k: &str) -> Option<&'a str> {
    e.get(k).and_then(|x| x.as_str())
}

fn f(e: &Value, k: &str) -> Option<f64> {
    e.get(k).and_then(|x| x.as_f64())
}

fn pt(v: &Value) -> Option<[f64; 3]> {
    let a = v.as_arr()?;
    Some([a.first()?.as_f64()?, a.get(1)?.as_f64()?, a.get(2).and_then(|z| z.as_f64()).unwrap_or(0.0)])
}

fn dist(a: [f64; 3], b: [f64; 3]) -> f64 {
    ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2) + (b[2] - a[2]).powi(2)).sqrt()
}

fn polyline_len(v: Option<&Value>) -> Option<f64> {
    let a = v?.as_arr()?;
    let pts: Vec<[f64; 3]> = a.iter().filter_map(pt).collect();
    if pts.len() < 2 {
        return None;
    }
    Some(pts.windows(2).map(|w| dist(w[0], w[1])).sum())
}

fn area_m2(v: Option<&Value>) -> Option<f64> {
    let a = v?.as_arr()?;
    let pts: Vec<[f64; 3]> = a.iter().filter_map(pt).collect();
    if pts.len() < 3 {
        return None;
    }
    let mut s = 0.0;
    for i in 0..pts.len() {
        let p = pts[i];
        let q = pts[(i + 1) % pts.len()];
        s += p[0] * q[1] - q[0] * p[1];
    }
    Some((s / 2.0).abs() / 1e6)
}

fn round2(x: f64) -> f64 {
    (x * 100.0).round() / 100.0
}

/// The name of a library entry an element's field names (its GUID).
fn lib_name(pr: &Project, e: &Value, k: &str) -> Option<String> {
    pr.lib_name(s(e, k)?)
}

fn el_name(pr: &Project, g: &str) -> Option<String> {
    let id = pr.find_guid(g)?;
    pr.el(id)?.get("name")?.as_str().map(|s| s.to_string())
}

/// The element a door or a window stands in.
fn host<'a>(pr: &'a Project, e: &Value) -> Option<(u64, &'a Value)> {
    let id = pr.find_guid(s(e, "host")?)?;
    Some((id, pr.el(id)?))
}

/// A type's properties (`types` of the category, or of runs) by the element's type.
fn type_props(pr: &Project, cat: &str, e: &Value) -> Option<Value> {
    let name = lib_name(pr, e, "type")?;
    let types = pr.section("types")?;
    if let Some(t) = types.get(cat).and_then(|m| m.get(&name)) {
        return Some(t.clone());
    }
    types.get("runs").and_then(|r| r.get(cat)).and_then(|m| m.get(&name)).cloned()
}

fn type_num(pr: &Project, cat: &str, e: &Value, k: &str) -> Option<f64> {
    type_props(pr, cat, e)?.get(k)?.as_f64()
}

/// The phase an element is made in (doors and windows follow their wall).
fn phase_of(pr: &Project, e: &Value, key: &str, depth: usize) -> Option<String> {
    if let Some(v) = e.get("params").and_then(|p| p.get(key)).and_then(|v| v.as_str()) {
        return Some(crate::styles::phasing::phase_name_of(pr, v));
    }
    let c = s(e, "category").unwrap_or("");
    if matches!(c, "door" | "window") && depth < 4 {
        if let Some((_, h)) = host(pr, e) {
            return phase_of(pr, h, key, depth + 1);
        }
    }
    if key == "Phase Created" {
        return crate::styles::phasing::phases(pr).first().cloned();
    }
    None
}

fn run_len(e: &Value) -> Option<f64> {
    let a = pt(e.get("start")?)?;
    let b = pt(e.get("end")?)?;
    let d = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
    let rise = f(e, "end_offset").map(|eo| eo - f(e, "offset").unwrap_or(0.0)).unwrap_or(0.0);
    Some((d * d + rise * rise).sqrt())
}

fn wall_len(e: &Value) -> Option<f64> {
    let a = pt(e.get("start")?)?;
    let b = pt(e.get("end")?)?;
    let chord = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
    match f(e, "arc") {
        Some(deg) if deg.abs() > 1e-9 => {
            let t = deg.abs().to_radians();
            Some(chord * (t / 2.0) / (t / 2.0).sin())
        }
        _ => Some(chord),
    }
}

/// An element's value of a field (None where it has none).
pub fn value_of(pr: &Project, cat: &str, id: u64, fd: &Field) -> Option<FV> {
    let e = pr.el(id)?;
    if let Some(g) = &fd.param {
        return match e.get("params").and_then(|p| p.get(g)) {
            Some(Value::Str(t)) => Some(FV::Text(t.clone())),
            Some(Value::Bool(b)) => Some(FV::Bool(*b)),
            Some(Value::Num(n)) => Some(FV::Num(n.as_f64())),
            _ => None,
        };
    }
    let num = |x: Option<f64>| x.map(FV::Num);
    let text = |x: Option<String>| x.filter(|t| !t.is_empty()).map(FV::Text);
    let len = |x: Option<f64>| x.map(|v| FV::Num(round2(v)));
    match fd.name.as_str() {
        "Id" => Some(FV::Num(id as f64)),
        "Count" => Some(FV::Num(1.0)),
        "Type" => {
            let n = lib_name(pr, e, "type")?;
            let n = if cat == "component" { n.split_once(": ").map(|(_, t)| t.to_string()).unwrap_or(n) } else { n };
            text(Some(n))
        }
        "Family" => text(lib_name(pr, e, "family")),
        "Level" => {
            let lv = match s(e, "level") {
                Some(g) => el_name(pr, g),
                None => host(pr, e).and_then(|(_, h)| s(h, "level").and_then(|g| el_name(pr, g))),
            };
            text(lv)
        }
        "Name" => text(s(e, "name").map(|x| x.to_string())),
        "Number" => text(s(e, "number").map(|x| x.to_string())),
        "Mark" => text(s(e, "mark").map(|x| x.to_string())),
        "Grade" => text(s(e, "grade").map(|x| x.to_string())),
        "Layer" => text(s(e, "layer").map(|x| x.to_string())),
        "System" => text(s(e, "system").and_then(|g| pr.lib_name(g).or_else(|| Some(g.to_string())))),
        "Elevation" => len(f(e, "elevation")),
        "Wall" => host(pr, e).map(|(h, _)| FV::Num(h as f64)),
        "Host" => s(e, "host").and_then(|g| pr.find_guid(g)).map(|h| FV::Num(h as f64)),
        "Sill" => len(f(e, "sill")),
        "Offset" => len(Some(f(e, "offset").unwrap_or(0.0))),
        "Structural" => Some(FV::Bool(e.get("structural").and_then(|x| x.as_bool()).unwrap_or(false))),
        "Slope" => num(f(e, "slope")),
        "Tread" => len(f(e, "tread")),
        "Diameter" => match cat {
            "rebar" => len(f(e, "diameter")),
            _ => len(type_num(pr, cat, e, "width")),
        },
        "Width" => match cat {
            "stair" | "ramp" => len(f(e, "width")),
            _ => len(type_num(pr, cat, e, "width")),
        },
        "Depth" => len(type_num(pr, cat, e, "depth")),
        "Thickness" => match cat {
            "footing" => len(f(e, "height")),
            _ => len(type_num(pr, cat, e, "thickness")),
        },
        "Height" => match cat {
            "door" | "window" => len(type_num(pr, cat, e, "height")),
            "railing" => len(type_num(pr, cat, e, "height")),
            _ => len(f(e, "height")),
        },
        "Length" => match cat {
            "wall" => len(wall_len(e)),
            "railing" => len(polyline_len(e.get("path"))),
            "rebar" => len(polyline_len(e.get("path"))),
            "stair" => {
                let h = f(e, "height")?;
                let r = f(e, "riser")?;
                let n = (h / r).ceil();
                len(Some((n - 1.0) * f(e, "tread")?))
            }
            "ramp" => {
                let h = f(e, "height")?;
                let sl = f(e, "slope")?;
                if sl.abs() < 1e-12 {
                    None
                } else {
                    len(Some(h / (sl / 100.0)))
                }
            }
            _ => len(run_len(e)),
        },
        "Risers" => {
            let h = f(e, "height")?;
            let r = f(e, "riser")?;
            num(Some((h / r).ceil()))
        }
        "Riser Height" => {
            let h = f(e, "height")?;
            let r = f(e, "riser")?;
            len(Some(h / (h / r).ceil()))
        }
        "Weight" => {
            let d = f(e, "diameter")?;
            let l = polyline_len(e.get("path"))?;
            num(Some(((d * d * 0.00617 * l / 1000.0) * 1000.0).round() / 1000.0))
        }
        "Area" => match cat {
            "floor" | "ceiling" => {
                let mut a = area_m2(e.get("boundary"))?;
                if let Some(holes) = e.get("openings").and_then(|o| o.as_arr()) {
                    for h in holes {
                        a -= area_m2(Some(h)).unwrap_or(0.0);
                    }
                }
                Some(FV::Num(round2(a)))
            }
            "mass" => area_m2(e.get("boundary")).map(|a| FV::Num(round2(a))),
            _ => None,
        },
        "Plan Area" => area_m2(e.get("boundary")).map(|a| FV::Num(round2(a))),
        "Phase Created" | "Phase Demolished" => text(phase_of(pr, e, &fd.name, 0)),
        "Design Option" => {
            let v = e.get("params").and_then(|p| p.get("Design Option")).and_then(|v| v.as_str())?;
            text(Some(crate::styles::common::name_of_guid(pr, "design-option", v).unwrap_or_else(|| v.to_string())))
        }
        _ => None,
    }
}

/// The elements of a category a filter picks from, by id.
pub fn elements_of(pr: &Project, cat: &str) -> Vec<u64> {
    if cat == "massfloor" {
        return Vec::new();
    }
    pr.ids_of(cat)
}

/// Whether a value holds a rule (`op`, against `v`).
pub fn holds(val: Option<&FV>, kind: Kind, op: &str, v: Option<&Value>) -> bool {
    match op {
        "has-value" => return val.is_some(),
        "has-no-value" => return val.is_none(),
        _ => {}
    }
    match kind {
        Kind::Text => {
            let a = match val {
                Some(FV::Text(t)) => Some(t.to_lowercase()),
                Some(FV::Num(n)) => Some(format!("{}", n)),
                Some(FV::Bool(b)) => Some(b.to_string()),
                None => None,
            };
            let b = v.and_then(|x| x.as_str()).unwrap_or("").to_lowercase();
            match (op, a) {
                ("equals", Some(a)) => a == b,
                ("equals", None) => b.is_empty(),
                ("not-equals", Some(a)) => a != b,
                ("not-equals", None) => !b.is_empty(),
                ("greater", Some(a)) => a > b,
                ("greater-or-equal", Some(a)) => a >= b,
                ("less", Some(a)) => a < b,
                ("less-or-equal", Some(a)) => a <= b,
                ("contains", Some(a)) => a.contains(&b),
                ("not-contains", Some(a)) => !a.contains(&b),
                ("not-contains", None) => true,
                ("begins-with", Some(a)) => a.starts_with(&b),
                ("not-begins-with", Some(a)) => !a.starts_with(&b),
                ("not-begins-with", None) => true,
                ("ends-with", Some(a)) => a.ends_with(&b),
                ("not-ends-with", Some(a)) => !a.ends_with(&b),
                ("not-ends-with", None) => true,
                _ => false,
            }
        }
        Kind::YesNo => {
            let a = match val {
                Some(FV::Bool(b)) => *b,
                _ => false,
            };
            let b = v.and_then(|x| x.as_bool()).unwrap_or(false);
            match op {
                "equals" => a == b,
                "not-equals" => a != b,
                _ => false,
            }
        }
        _ => {
            let Some(FV::Num(a)) = val else { return op == "not-equals" };
            let Some(b) = v.and_then(|x| x.as_f64()) else { return false };
            let eq = (a - b).abs() < 1e-9;
            match op {
                "equals" => eq,
                "not-equals" => !eq,
                "greater" => *a > b && !eq,
                "greater-or-equal" => *a > b || eq,
                "less" => *a < b && !eq,
                "less-or-equal" => *a < b || eq,
                _ => false,
            }
        }
    }
}

//! View filters: `filter`.
//!
//! The file keeps `view_filters` (name: {categories, rules?}, sorted by name, the section gone
//! with its last filter) and a `view-filter` library entry for each. A rule is a schedule
//! filter's: {field, op, value?}, a project parameter's field by its GUID and a value naming a
//! phase (or a design option) by its GUID. Views apply filters by GUID (`graphics.filters`).

#![allow(unused_imports)]

pub mod fields;

use super::common::*;
use super::graphics::ovr::{self, sorted_items};
use super::graphics::vg;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;
use fields::Kind;

/// The categories a filter picks from, as the original lists them.
pub const CATEGORIES: &[&str] = &[
    "room",
    "door",
    "window",
    "wall",
    "floor",
    "ceiling",
    "roof",
    "column",
    "structuralcolumn",
    "footing",
    "beam",
    "rebar",
    "stripfooting",
    "pipe",
    "conduit",
    "cabletray",
    "duct",
    "cable",
    "downconductor",
    "groundconductor",
    "wire",
    "component",
    "stair",
    "ramp",
    "railing",
    "mass",
    "massfloor",
    "level",
];

pub const OPS: &[&str] = &[
    "equals",
    "not-equals",
    "greater",
    "greater-or-equal",
    "less",
    "less-or-equal",
    "contains",
    "not-contains",
    "begins-with",
    "not-begins-with",
    "ends-with",
    "not-ends-with",
    "has-value",
    "has-no-value",
];

/// Runs the commands of this part.
pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "filter" => cmd_filter(s, p),
        _ => Err(format!("{}: not supported here", cid)),
    }
}

/// The project's view filters (name: as the file holds it).
pub fn view_filters(pr: &Project) -> Map {
    pr.section("view_filters").cloned().unwrap_or_default()
}

fn set_view_filters(pr: &mut Project, m: Map) {
    if m.is_empty() {
        pr.remove_top("view_filters");
    } else {
        pr.insert_top("view_filters", Value::Obj(m));
    }
}

/// A name a command is given: text, trimmed, of 1 to 256 characters.
pub fn name_param(p: &Value, cmd: &str, key: &str) -> R<Option<String>> {
    match p.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(Value::Str(s)) if s.chars().count() <= 256 => {
            let t = s.trim();
            Ok(if t.is_empty() { None } else { Some(t.to_string()) })
        }
        Some(v) => Err(format!("{}: `{}` must be text of at most 256 characters, got {}", cmd, key, v.to_compact())),
    }
}

/// A category filters pick from, else the original's message.
fn filter_category(cmd: &str, s: &str) -> R<String> {
    vg::singular_in(s, CATEGORIES).ok_or_else(|| {
        format!("{}: `{}` isn't a category filters pick from; there are: {}", cmd, s, CATEGORIES.join(", "))
    })
}

/// A rule as a command gives it.
#[derive(Clone, Debug)]
pub struct Rule {
    pub field: String,
    pub op: String,
    pub value: Option<Value>,
}

impl Rule {
    /// The rule as a reply shows it (and as the command gave it).
    pub fn value(&self) -> Value {
        let mut m = Map::new();
        m.insert("field", Value::s(&self.field));
        m.insert("op", Value::s(&self.op));
        if let Some(v) = &self.value {
            m.insert("value", v.clone());
        }
        Value::Obj(m)
    }
}

/// A rule as serde reads it: {field, op, value?}.
fn de_rule(v: &Value) -> R<Rule> {
    let m = match v {
        Value::Obj(m) => m,
        _ => return Err(format!("invalid type: {}, expected struct Filter", v.kind_name())),
    };
    let mut field = None;
    let mut op = None;
    let mut value = None;
    for (k, x) in sorted_items(m) {
        match k.as_str() {
            "field" => field = Some(ovr::de_string(&x)?),
            "op" => match &x {
                Value::Str(s) if OPS.contains(&s.as_str()) => op = Some(s.clone()),
                Value::Str(s) => {
                    let list: Vec<String> = OPS.iter().map(|o| format!("`{}`", o)).collect();
                    return Err(format!("unknown variant `{}`, expected one of {}", s, list.join(", ")));
                }
                _ => return Err(format!("invalid type: {}, expected string or map", x.kind_name())),
            },
            "value" => {
                value = if x.is_null() { None } else { Some(x.clone()) };
            }
            _ => return Err(format!("unknown field `{}`, expected one of `field`, `op`, `value`", k)),
        }
    }
    let field = field.ok_or_else(|| "missing field `field`".to_string())?;
    let op = op.ok_or_else(|| "missing field `op`".to_string())?;
    Ok(Rule { field, op, value })
}

/// A rule as the file holds it, read back by name.
fn named_rule(pr: &Project, cats: &[String], r: &Value) -> Rule {
    let mut field = r.get("field").and_then(|x| x.as_str()).unwrap_or("").to_string();
    if let Some(n) = crate::styles::common::name_of_guid(pr, "parameter", &field) {
        field = n;
    }
    let _ = cats;
    let op = r.get("op").and_then(|x| x.as_str()).unwrap_or("").to_string();
    let mut value = r.get("value").cloned();
    if let Some(Value::Str(v)) = &value {
        let named = match field.as_str() {
            "Phase Created" | "Phase Demolished" => crate::styles::common::name_of_guid(pr, "phase", v),
            "Design Option" => crate::styles::common::name_of_guid(pr, "design-option", v),
            _ => None,
        };
        if let Some(n) = named {
            value = Some(Value::s(&n));
        }
    }
    Rule { field, op, value }
}

/// A filter's categories as the file holds them.
fn cats_of(f: &Value) -> Vec<String> {
    f.get("categories")
        .and_then(|c| c.as_arr())
        .map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect())
        .unwrap_or_default()
}

/// A filter's rules, by name.
fn rules_of(pr: &Project, f: &Value) -> Vec<Rule> {
    let cats = cats_of(f);
    f.get("rules").and_then(|r| r.as_arr()).map(|a| a.iter().map(|r| named_rule(pr, &cats, r)).collect()).unwrap_or_default()
}

/// A rule's value against what its field holds: "filter on `F`: …", or None where it holds.
fn rule_error(r: &Rule, kind: Kind) -> Option<String> {
    if matches!(r.op.as_str(), "has-value" | "has-no-value") {
        return None;
    }
    let text_op = matches!(
        r.op.as_str(),
        "contains" | "not-contains" | "begins-with" | "not-begins-with" | "ends-with" | "not-ends-with"
    );
    let shown = r.value.as_ref().map(|v| v.to_compact()).unwrap_or_else(|| "null".into());
    let pre = format!("filter on `{}`: ", r.field);
    match kind {
        Kind::Text => match &r.value {
            Some(Value::Str(_)) => None,
            _ => Some(format!("{}it compares text, not {}", pre, shown)),
        },
        Kind::YesNo => {
            if !matches!(r.op.as_str(), "equals" | "not-equals") {
                return Some(format!("{}yes or no only equals or doesn't", pre));
            }
            match &r.value {
                Some(Value::Bool(_)) => None,
                _ => Some(format!("{}it compares yes or no, not {}", pre, shown)),
            }
        }
        _ => {
            if text_op {
                return Some(format!("{}it holds {}, and only text contains, begins or ends", pre, kind.holds()));
            }
            match &r.value {
                Some(Value::Num(_)) => None,
                _ => Some(format!("{}it compares {}, not {}", pre, kind.compares(), shown)),
            }
        }
    }
}

/// Checks rules against categories (each field one of every category's, its value of its kind),
/// as a schedule's filters are checked; the message after `filter: `.
fn check_rules(pr: &Project, cats: &[String], rules: &[Rule]) -> R<Vec<(Rule, Vec<fields::Field>)>> {
    let mut out = Vec::new();
    for r in rules {
        let mut fs = Vec::new();
        for c in cats {
            match fields::field(pr, c, &r.field) {
                Some(f) => fs.push(f),
                None => {
                    let names: Vec<String> = fields::fields_of(pr, c).into_iter().map(|f| f.name).collect();
                    return Err(format!(
                        "filter: `{}` isn't a field of {}s; there are: {}",
                        r.field,
                        c,
                        names.join(", ")
                    ));
                }
            }
        }
        if let Some(f) = fs.first() {
            if let Some(e) = rule_error(r, f.kind) {
                return Err(e);
            }
        }
        out.push((r.clone(), fs));
    }
    Ok(out)
}

/// The elements a filter picks out, by id.
pub fn matches(pr: &Project, cats: &[String], rules: &[Rule]) -> Vec<u64> {
    let mut ids = Vec::new();
    for c in cats {
        let fs: Vec<Option<fields::Field>> = rules.iter().map(|r| fields::field(pr, c, &r.field)).collect();
        for id in fields::elements_of(pr, c) {
            let ok = rules.iter().zip(fs.iter()).all(|(r, f)| match f {
                Some(f) => {
                    let v = fields::value_of(pr, c, id, f);
                    fields::holds(v.as_ref(), f.kind, &r.op, r.value.as_ref())
                }
                None => false,
            });
            if ok {
                ids.push(id);
            }
        }
    }
    ids.sort();
    ids.dedup();
    ids
}

/// The elements the project's filter of this name picks out.
pub fn matches_of(pr: &Project, name: &str) -> Vec<u64> {
    let Some(f) = view_filters(pr).get(name).cloned() else { return Vec::new() };
    let cats = cats_of(&f);
    let rules = rules_of(pr, &f);
    matches(pr, &cats, &rules)
}

/// A rule as the file holds it: a project parameter by its GUID, a phase or a design option it
/// names exactly by its GUID.
fn file_rule(pr: &Project, r: &Rule, fs: &[fields::Field]) -> Value {
    let field = fs.first().and_then(|f| f.param.clone()).unwrap_or_else(|| r.field.clone());
    let mut m = Map::new();
    m.insert("field", Value::s(&field));
    m.insert("op", Value::s(&r.op));
    if let Some(v) = &r.value {
        let mut v = v.clone();
        if let Value::Str(t) = &v {
            let g = match r.field.as_str() {
                "Phase Created" | "Phase Demolished" => {
                    if crate::styles::phasing::phases(pr).iter().any(|x| x == t) {
                        pr.lib_guid("phase", t)
                    } else {
                        None
                    }
                }
                "Design Option" => pr.lib_guid("design-option", t),
                _ => None,
            };
            if let Some(g) = g {
                v = Value::s(&g);
            }
        }
        m.insert("value", v);
    }
    Value::Obj(m)
}

fn reply(pr: &Project, name: &str, cats: &[String], rules: &[Rule]) -> Value {
    jobj! {
        "categories" => cats.to_vec(),
        "matches" => matches(pr, cats, rules),
        "name" => name,
        "rules" => Value::Arr(rules.iter().map(|r| r.value()).collect()),
    }
}

fn cmd_filter(s: &mut Session, p: &Value) -> R<Value> {
    let cmd = "filter";
    let name = name_param(p, cmd, "name")?.ok_or_else(|| format!("{}: `name` is required", cmd))?;
    let delete = crate::commands::params::opt_bool(p, cmd, "delete")?.unwrap_or(false);
    let pr = &mut s.project;
    let mut all = view_filters(pr);
    if delete {
        if !all.contains(&name) {
            return Err(format!("{}: there's no view filter `{}`", cmd, name));
        }
        delete_filter(pr, &name);
        return Ok(jobj! {"deleted" => true, "name" => name});
    }
    let cats_given = match get(p, "categories") {
        None => None,
        Some(Value::Arr(a)) => {
            let mut out: Vec<String> = Vec::new();
            for x in a {
                match x {
                    Value::Str(c) => {
                        let c = filter_category(cmd, c)?;
                        if !out.contains(&c) {
                            out.push(c);
                        }
                    }
                    _ => return Err(format!("{}: `categories`: {} is not a category", cmd, x.to_compact())),
                }
            }
            out.sort();
            if out.is_empty() {
                return Err(format!("{}: it needs categories, one or more of: {}", cmd, CATEGORIES.join(", ")));
            }
            Some(out)
        }
        Some(v) => {
            return Err(format!(
                "{}: `categories` is a list of categories, [\"walls\", \"doors\"…], not {}",
                cmd,
                v.to_compact()
            ))
        }
    };
    let rules_given = match get(p, "rules") {
        None => None,
        Some(Value::Arr(a)) if a.len() <= 64 => {
            let mut out = Vec::new();
            for x in a {
                out.push(de_rule(x).map_err(|e| format!("{}: rule {}: {}", cmd, x.clone().sorted().to_compact(), e))?);
            }
            Some(out)
        }
        Some(v) => return Err(format!("{}: `rules` is [{{field, op, value}}, …] (up to 64), not {}", cmd, v.to_compact())),
    };
    let existing = all.get(&name).cloned();
    if existing.is_none() && cats_given.is_none() {
        return Err(format!("{}: a new filter needs `categories`, [\"walls\", \"doors\"…]", cmd));
    }
    let cats = match cats_given {
        Some(c) => c,
        None => cats_of(existing.as_ref().unwrap()),
    };
    let rules = match rules_given {
        Some(r) => r,
        None => existing.as_ref().map(|f| rules_of(pr, f)).unwrap_or_default(),
    };
    let checked = check_rules(pr, &cats, &rules).map_err(|e| format!("{}: {}", cmd, e))?;
    let mut f = Map::new();
    f.insert("categories", Value::from(cats.clone()));
    if !checked.is_empty() {
        f.insert("rules", Value::Arr(checked.iter().map(|(r, fs)| file_rule(pr, r, fs)).collect()));
    }
    all.insert_sorted(&name, Value::Obj(f));
    set_view_filters(pr, all);
    crate::styles::common::lib_ensure(pr, "view-filter", &name);
    Ok(reply(pr, &name, &cats, &rules))
}

/// Takes a filter away: its entry, and every view and template stops applying it.
pub fn delete_filter(pr: &mut Project, name: &str) {
    let gd = pr.lib_guid("view-filter", name);
    let mut all = view_filters(pr);
    all.remove(name);
    set_view_filters(pr, all);
    crate::styles::common::lib_remove(pr, "view-filter", name);
    let Some(gd) = gd else { return };
    fn strip(g: &mut Map, gd: &str) {
        if let Some(Value::Arr(a)) = g.get("filters").cloned() {
            let kept: Vec<Value> = a.into_iter().filter(|f| f.get("filter").and_then(|x| x.as_str()) != Some(gd)).collect();
            vg::gput(g, "filters", if kept.is_empty() { None } else { Some(Value::Arr(kept)) });
        }
    }
    let ids: Vec<u64> = pr.elements.keys().copied().collect();
    for id in ids {
        let mut g = vg::own(pr, id);
        if g.contains("filters") {
            let before = g.clone();
            strip(&mut g, &gd);
            if g != before {
                vg::store_in(pr, id, g);
            }
        }
    }
    if let Some(Value::Obj(ts)) = pr.doc.get_mut("view_templates") {
        for (_, t) in ts.items.iter_mut() {
            if let Some(Value::Obj(g)) = t.get_mut("graphics") {
                strip(g, &gd);
                if g.is_empty() {
                    t.remove("graphics");
                }
            }
        }
    }
}

/// The model rules of this part, checked after every command.
pub fn check(pr: &Project) -> R<()> {
    let _ = pr;
    Ok(())
}

/// What `inspect` says of the sections this part keeps: the view filters, by name, their rules'
/// fields and values named.
pub fn inspect_entries(s: &Session, out: &mut Vec<(String, Value)>) {
    let pr = &s.project;
    let mut m = Map::new();
    for (k, f) in &view_filters(pr).items {
        let mut e = Map::new();
        e.insert("categories", Value::from(cats_of(f)));
        if f.get("rules").and_then(|r| r.as_arr()).map(|a| !a.is_empty()).unwrap_or(false) {
            e.insert("rules", Value::Arr(rules_of(pr, f).iter().map(|r| r.value()).collect()));
        }
        m.insert(k, Value::Obj(e));
    }
    out.push(("view_filters".into(), Value::Obj(m)));
}

