#!/usr/bin/env python3
"""insp.py [-f in.bimcraft] cmds.txt: each line's commands, then `inspect {}`, on both programs;
compares inspect's view_filters and view_templates (and the history), and the saved file's
elements of view categories and the view_filters/view_templates sections."""
import json, os, subprocess, sys, tempfile, shutil, re
ORIG = '/workspace/executable'
MINE = os.environ['MINE']
G = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
a = sys.argv[1:]
infile = None
if a and a[0] == '-f':
    infile = a[1]; a = a[2:]
lines = [l.rstrip('\n') for l in open(a[0]) if l.strip() and not l.startswith('#')]
VIEWS = ('level', 'planview', 'section', 'elevation', 'view3d')
def norm(s):
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return G.sub(rep, s)
def run(exe, l):
    d = tempfile.mkdtemp(prefix='i', dir=os.environ.get('SCRATCH'))
    args = [exe, 'run']
    if infile:
        shutil.copy(infile, d); args.append(os.path.basename(infile))
    for c in l.split(' ;; '):
        args += ['--cmd', c]
    args += ['--cmd', 'inspect {}', '--save', 'out.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True, timeout=120)
    out = p.stdout.decode().strip().split('\n')
    res = {'err': p.stderr.decode().strip(), 'code': p.returncode}
    try:
        ins = json.loads(out[-2])
        res['inspect'] = {k: ins.get(k) for k in ('view_filters', 'view_templates', 'history')}
    except Exception as e:
        res['inspect'] = 'none'
    try:
        f = json.load(open(os.path.join(d, 'out.bimcraft')))
        res['file'] = {
            'els': {k: v for k, v in f['elements'].items() if v.get('category') in VIEWS},
            'vf': f.get('view_filters'), 'vt': f.get('view_templates'),
            'lib': sorted([(v['kind'], v['name']) for v in f['library'].values() if v['kind'] in ('view-filter', 'view-template')]),
            'keys': [k for k in f.keys()],
        }
    except Exception as e:
        res['file'] = 'none'
    shutil.rmtree(d)
    return norm(json.dumps(res))
same = 0
for l in lines:
    o = run(ORIG, l); m = run(MINE, l)
    if o == m:
        same += 1; print('SAME', l[:150])
    else:
        print('DIFF', l)
        oj = json.loads(o); mj = json.loads(m)
        for k in oj:
            if oj[k] != mj.get(k):
                print('  orig', k, json.dumps(oj[k])[:1500])
                print('  mine', k, json.dumps(mj.get(k))[:1500])
print('%d/%d same' % (same, len(lines)))

