    super::filters::check_all(pr)?;
    super::templates::check_all(pr)?;
    for (id, e) in &pr.elements {
        let Some(Value::Obj(g)) = e.get("graphics") else { continue };
        if !takes_graphics(cat(e)) {
            continue;
        }
        edit::check(pr, g).map_err(|m| format!("{} {}: {}", cat(e), id, m))?;
    }
    Ok(())
}

