import math
def per(r, n, rnd, phase=0.0, cx=2000, cy=2000):
    pts = []
    for i in range(n):
        t = 2 * math.pi * i / n + phase
        x, y = cx + r * math.cos(t), cy + r * math.sin(t)
        if rnd is not None:
            x, y = round(x / rnd) * rnd, round(y / rnd) * rnd
        pts.append((x, y))
    p = sum(math.dist(pts[i], pts[(i + 1) % n]) for i in range(n))
    a = abs(sum(pts[i][0] * pts[(i + 1) % n][1] - pts[(i + 1) % n][0] * pts[i][1] for i in range(n))) / 2
    return p, a
for rnd in [None, 1.0, 0.001]:
