        (0..24)
            .map(|i| {
                let a = i as f64 / 24.0 * std::f64::consts::TAU;
                [at[0] + w / 2.0 * a.cos(), at[1] + w / 2.0 * a.sin()]
            })
            .collect::<Vec<P>>()
    })
} else {
    m::outline(pr, *id)
};
if let Some(mut o) = o {
