#!/usr/bin/env python3
"""Random sequences of graphics/template/filter/scale/detail/visual_style commands on both programs;
compares every output line and the saved file's view elements and sections."""
import json, os, random, re, subprocess, sys, tempfile, shutil
ORIG = '/workspace/executable'
MINE = os.environ['MINE']
G = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
n = int(sys.argv[2]) if len(sys.argv) > 2 else 50
infile = '/tmp/views-graphics/base2.bimcraft'
rnd = random.Random(seed)
VIEWS = ['Level 1', 'Level 2', 'Section 1', 'South', 'Camera 1', '{3D}', 'Level 1 Copy 1', 'Level 1 Dependent 1', 100014, 100002, 'nope']
CATS = ['walls', 'doors', 'rooms', 'Windows', 'furniture', 'roomreference', 'grids', 'levels', 'mass', 'component', 'zzz', 'lighting', 'casework']
TPLS = ['Electrical Power', 'Electrical Lighting', 'T1', 'T2', 'nope']
FILTERS = ['F1', 'F2', 'nope']
def color():
    return rnd.choice([[1, 2, 3], '#ff0000', [255, 255, 255], 'red', [300, 0, 0]])
def style():
    s = {}
    for k in rnd.sample(['color', 'weight', 'dash', 'fill', 'foreground', 'background'], rnd.randint(0, 3)):
        if k in ('color', 'fill'):
            s[k] = color()
        elif k == 'weight':
            s[k] = rnd.choice([0, 3, 16, 17, 1.5])
        elif k == 'dash':
            s[k] = rnd.choice(['solid', 'dashed', 'dotted', 'dashdot'])
        else:
            s[k] = rnd.choice([None, {'pattern': 'Diagonal Up'}, {'pattern': None, 'color': [1, 1, 1]}, {'color': [9, 9, 9]}, {'pattern': 'Nope'}])
    return s
def override():
    o = {}
    for k in rnd.sample(['hidden', 'projection', 'cut', 'halftone', 'transparency', 'shown'], rnd.randint(0, 3)):
        if k in ('hidden', 'halftone', 'shown'):
            o[k] = rnd.choice([True, False, None])
        elif k == 'transparency':
            o[k] = rnd.choice([0, 20, 100, 101])
        else:
            o[k] = rnd.choice([style(), None])
    return o
def gparams(template=False):
    p = {}
    keys = ['hide', 'show', 'categories', 'filters', 'phase', 'phase_filter', 'options', 'background_grid', 'reset']
    if not template:
        keys += ['hide_elements', 'show_elements', 'elements', 'layers', 'template']
    for k in rnd.sample(keys, rnd.randint(1, 3)):
        if k in ('hide', 'show'):
            p[k] = rnd.sample(CATS, rnd.randint(0, 2))
        elif k == 'categories':
            p[k] = {c: rnd.choice([override(), None]) for c in rnd.sample(CATS, rnd.randint(1, 2))}
        elif k == 'filters':
            p[k] = [dict({'filter': f}, **{kk: vv for kk, vv in override().items() if kk != 'shown'}) for f in rnd.sample(FILTERS, rnd.randint(0, 2))]
        elif k == 'phase':
            p[k] = rnd.choice(['Existing', 'New Construction', None, 'nope'])
        elif k == 'phase_filter':
            p[k] = rnd.choice(['Show All', 'Show New', None, 'nope'])
        elif k == 'options':
            p[k] = rnd.choice([{'S1': 'B'}, {'S1': None}, {'S1': 'A'}, {'S1': 'Z'}])
        elif k == 'background_grid':
            p[k] = rnd.choice([None, {'visible': False}, {'main': {'enabled': True, 'pen': 3}}, {'spacing': [500, 500]}, {'rotation': 400}])
        elif k == 'reset':
            p[k] = rnd.choice([True, False])
        elif k in ('hide_elements', 'show_elements'):
            p[k] = rnd.sample([100002, 100006, 100010, 100014, 12345], rnd.randint(0, 2))
        elif k == 'elements':
            p[k] = {str(i): rnd.choice([override(), None]) for i in rnd.sample([100002, 100006, 100010], rnd.randint(1, 2))}
        elif k == 'layers':
            p[k] = rnd.choice([{'a': ['WALLS']}, {'a': None}, {'a': ['FURN', 'WALLS']}, {'b': ['x']}])
        elif k == 'template':
            p[k] = rnd.choice(TPLS + [None])
    return p
def command():
    r = rnd.random()
    if r < 0.45:
        p = gparams()
        if rnd.random() < 0.8:
            p['view'] = rnd.choice(VIEWS)
        return 'graphics ' + json.dumps(p)
    if r < 0.7:
        p = gparams(template=True)
        p['name'] = rnd.choice(TPLS[:4])
        for k in rnd.sample(['from', 'like', 'kind', 'controls', 'scale', 'detail', 'visual_style', 'view_range', 'rename', 'delete'], rnd.randint(0, 2)):
            if k == 'from':
                p[k] = rnd.choice(VIEWS)
            elif k == 'like':
                p[k] = rnd.choice(TPLS)
            elif k == 'kind':
                p[k] = rnd.choice(['plan', 'section', '3d', None, 'x'])
            elif k == 'controls':
                p[k] = rnd.sample(['categories', 'filters', 'range', 'phase', 'options', 'scale', 'detail', 'style', 'background_grid'], rnd.randint(0, 3))
            elif k == 'scale':
                p[k] = rnd.choice([50, 100, 0])
            elif k == 'detail':
                p[k] = rnd.choice(['coarse', 'fine', 'x'])
            elif k == 'visual_style':
                p[k] = rnd.choice(['wireframe', 'shaded', 'x'])
            elif k == 'view_range':
                p[k] = rnd.choice([{'cut': 1000}, {'top': 2000}, {'bottom': 5000}])
            elif k == 'rename':
                p[k] = rnd.choice(['T3', 'T1', 'Electrical Power'])
            elif k == 'delete':
                p[k] = rnd.random() < 0.3
        return 'template ' + json.dumps(p)
    if r < 0.8:
        p = {'view': rnd.choice(VIEWS)}
        if rnd.random() < 0.7:
            p['scale'] = rnd.choice([20, 50, 100, 0, None])
        return 'scale ' + json.dumps(p)
    if r < 0.88:
        p = {'view': rnd.choice(VIEWS)}
        if rnd.random() < 0.7:
            p['detail'] = rnd.choice(['coarse', 'medium', 'fine', None])
        return 'detail ' + json.dumps(p)
    if r < 0.94:
        p = {}
        if rnd.random() < 0.6:
            p['view'] = rnd.choice(VIEWS)
        if rnd.random() < 0.7:
            p['style'] = rnd.choice(['shaded', 'wireframe', 'hidden_line'])
        return 'visual_style ' + json.dumps(p)
    p = {'name': rnd.choice(FILTERS)}
    if rnd.random() < 0.7:
        p['categories'] = rnd.sample(['walls', 'doors', 'windows', 'rooms'], rnd.randint(1, 2))
    if rnd.random() < 0.3:
        p['delete'] = True
    return 'filter ' + json.dumps(p)
def norm(s):
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return G.sub(rep, s)
def run(exe, cmds):
    d = tempfile.mkdtemp(prefix='z', dir=os.environ.get('SCRATCH'))
    shutil.copy(infile, d)
    outs = []
    # one process per command sequence, the project saved after each, so errors don't stop it
    for i, c in enumerate(cmds):
        src = 'base2.bimcraft' if i == 0 else 'cur.bimcraft'
        p = subprocess.run([exe, 'run', src, '--cmd', c, '--save', 'next.bimcraft'], cwd=d, capture_output=True, text=True)
        out = p.stdout.strip().split('\n')
        outs.append((out[1] if len(out) > 1 else '', p.stderr.strip()))
        if os.path.exists(os.path.join(d, 'next.bimcraft')):
            shutil.move(os.path.join(d, 'next.bimcraft'), os.path.join(d, 'cur.bimcraft'))
        elif i == 0:
            shutil.copy(os.path.join(d, 'base2.bimcraft'), os.path.join(d, 'cur.bimcraft'))
    f = json.load(open(os.path.join(d, 'cur.bimcraft')))
    shutil.rmtree(d)
    els = {k: v for k, v in f['elements'].items() if v.get('category') in ('level', 'planview', 'section', 'elevation', 'view3d')}
    return outs, norm(json.dumps({'els': els, 'vf': f.get('view_filters'), 'vt': f.get('view_templates'), 'next': f.get('next_id'),
                                  'lib': sorted([(v['kind'], v['name']) for v in f['library'].values() if v['kind'] in ('view-filter', 'view-template')])}))
cmds = [command() for _ in range(n)]
oo, of = run(ORIG, cmds)
mo, mf = run(MINE, cmds)
bad = 0
for i, c in enumerate(cmds):
    if norm(json.dumps(oo[i])) != norm(json.dumps(mo[i])):
        bad += 1
        print('DIFF at', i, c)
        print('   orig', norm(json.dumps(oo[i]))[:600])
        print('   mine', norm(json.dumps(mo[i]))[:600])
        break
if of != mf and bad == 0:
    print('FILE DIFF')
    print('   orig', of[:3000])
    print('   mine', mf[:3000])
    bad += 1
print('seed', seed, 'OK' if bad == 0 else 'BAD')

