/// The project's view filters (name: as the file holds it).
pub fn view_filters(pr: &Project) -> Map {
    pr.section("view_filters").cloned().unwrap_or_default()
}

/// The view filter a name names, by its GUID; else the original's message.
pub fn filter_ref(pr: &Project, cmd: &str, name: &str) -> R<String> {
    let vf = view_filters(pr);
    if vf.contains(name) {
        if let Some(gd) = pr.lib_guid("view-filter", name) {
            return Ok(gd);
        }
    }
    let mut names: Vec<String> = vf.keys().cloned().collect();
    names.sort();
    Err(format!("{}: there's no view filter `{}`{}", cmd, name, there_are(&names)))
}

